window.LHS_ROOMS = [{"title": "The GP Consulting Room", "topic": "Systems thinking and boundaries", "subtitle": "A patient experiences one evolving health problem across services. Which parts of the system must be examined before reaching conclusions?", "lobby": "At 11 weeks, a pregnant patient presents to her GP with spotting. Reassuring imaging is followed by persistent symptoms, a public antenatal appointment, referral to a private obstetrician and later an ED presentation. Reconstruct the system, not the clinical verdict.", "mission": "Map interacting services, distinguish a documented encounter from an unverified handover, and choose a manageable boundary for an initial LHS investigation.", "conclusion": "The relevant system includes primary care, private specialist care and public hospital services, while the lead organisation may control only part of this journey. A boundary spanning the key interfaces is warranted; no failed handover or preventable clinical outcome has been established.", "fields": [["population", "Patient population and time window", "Whose journeys and what time span?"], ["learning", "System-level learning question", "What interaction or pattern needs investigating?"], ["sources", "Critical services and perspectives", "Include independent primary-care and hospital interfaces."], ["quality", "Confirmed facts versus hypotheses", "What is known? What needs verification?"], ["governance", "Boundary and responsibility", "Which organisation can lead; who must partner?"], ["investment", "First systems-scoping action", "What mapping or evidence collection comes first?"]], "refs": ["Foley & Horwitz (2025), Learning Health Systems, Section 3.", "Plsek & Greenhalgh (2001), The challenge of complexity in health care.", "General Practice in Australia primer, pp. 1, 4–5."], "witnesses": [{"id": "gp", "name": "The GP", "role": "Primary care and longitudinal records", "short": "What does the GP know before and after hospital care?", "intro": "The GP arranged early imaging and later referred the patient for a private obstetric opinion. The practice maintains its own record; which records other providers received is not established.", "opening": "In Australian general practice, consultations, results, referrals and correspondence are normally held in the practice clinical system; referrals and messages can transfer information, but no single record automatically follows the patient.", "q": [{"title": "GP–1 · Establish the boundary", "prompt": "Which first step best characterises the cross-service problem without assuming that communication failed?", "options": [{"text": "Audit GP referral letters to determine whether relevant symptoms were documented.", "feedback": "A referral audit is useful but isolates one document before mapping the full journey.", "branch": "You may establish what the GP sent, but not necessarily what later services knew."}, {"text": "Map the services, decision points and expected information interfaces from first GP review through hospital assessment.", "feedback": "Best: a whole-journey map identifies where focused document tracing is warranted.", "branch": "The next evidence can be targeted to specific interfaces rather than collected indiscriminately."}, {"text": "Ask the patient which clinician coordinated her care and investigate that professional’s actions.", "feedback": "The answer may illuminate perceived continuity but could prematurely assume a single coordinating professional.", "branch": "A patient can describe the journey without knowing all organisational responsibilities."}, {"text": "Extract data from My Health Record to reconstruct the sequence of consultations.", "feedback": "Selected shared documents may help, but My Health Record is not the complete primary-care record.", "branch": "The record may omit relevant consultation detail or private correspondence."}], "correct": 1, "newEvidence": ""}, {"title": "GP–2 · Interpret a gap", "prompt": "The public antenatal note does not mention the private obstetric consultation. What is justified?", "options": [{"text": "The specialist failed to communicate with the public hospital.", "feedback": "Absence from one note does not establish that no message was sent.", "branch": "Check message routing, dates, recipients and the local record."}, {"text": "The hospital did not review the specialist advice.", "feedback": "The note alone cannot establish what was available or reviewed.", "branch": "Check accessible documents, consultations and staff recollections."}, {"text": "The communication pathway is an interface to investigate; transfer, availability and use remain unverified.", "feedback": "Best: this preserves uncertainty and specifies a testable handover question.", "branch": "Trace generation, transmission, receipt, accessibility and use separately."}, {"text": "The specialist advice was unlikely to affect public antenatal care.", "feedback": "Clinical relevance cannot be inferred without the content and context.", "branch": "Request clinical interpretation before assigning relevance."}], "correct": 2, "newEvidence": "Additional evidence: a referral being written, a letter being received and a clinician acting on its content are distinct events."}], "clue": "A cross-service investigation must track which information existed and what transfers can actually be verified.", "basis": "GP primer; Foley & Horwitz 2025."}, {"id": "ed", "name": "The ED clinician", "role": "Acute assessment and operational constraints", "short": "Which departments and resources shape an ED encounter?", "intro": "The patient later attends ED with heavier bleeding. Her assessment involves acute clinical priorities, investigations and potential specialist input. Avoid judging appropriateness from waiting time alone.", "opening": "A hypothetical ED operational extract records presentation and investigation timestamps. It does not provide a complete account of triage, clinical acuity or capacity on that day.", "q": [{"title": "ED–1 · Explain the wait", "prompt": "What is the most useful starting explanation for a prolonged ED visit?", "options": [{"text": "Measure ED staffing and acuity at the time of presentation.", "feedback": "These factors matter, but may not explain diagnostic and specialist dependencies.", "branch": "A staffing-only analysis may miss bottlenecks outside the department."}, {"text": "Review ultrasound scheduling because imaging contributes substantially to the total wait.", "feedback": "Imaging may matter, but the sequence needs other service dependencies too.", "branch": "One timestamp does not establish the cause of the total delay."}, {"text": "Examine the sequence of clinical decisions alongside diagnostics, consultation availability and bed capacity.", "feedback": "Best: evaluates interacting clinical and operational factors without presuming fault.", "branch": "You can identify dependencies and then investigate the most consequential intervals."}, {"text": "Compare this visit with ED-wide median waiting times.", "feedback": "A comparator helps quantify unusual waits but may ignore clinical context and maternity pathways.", "branch": "Case-mix and service-specific processes still require interpretation."}], "correct": 2, "newEvidence": ""}, {"title": "ED–2 · Consider unintended effects", "prompt": "A proposed direct maternity pathway is expected to reduce some ED attendances. What must be examined?", "options": [{"text": "Potential benefits for access and possible effects on maternity staffing, safety and escalation.", "feedback": "Best: assesses how changing one part of the system influences another.", "branch": "The pathway requires eligibility, capacity and balancing measures."}, {"text": "Whether comparable hospitals have reduced their ED activity with such pathways.", "feedback": "External evidence is useful but local context and clinical suitability matter.", "branch": "A positive example may not transfer unchanged."}, {"text": "Whether patients report improved access after avoiding the ED.", "feedback": "Experience is vital but cannot establish clinical safety or wider resource effects alone.", "branch": "Include clinician and operational evidence."}, {"text": "Whether total hospital length of stay falls after implementation.", "feedback": "This is a useful system metric but not a complete measure of benefit or burden.", "branch": "Workload may be shifted rather than removed."}], "correct": 0, "newEvidence": "Additional evidence: a new pathway could reduce one bottleneck while increasing work elsewhere; these effects are hypotheses to evaluate."}], "clue": "ED performance depends on other services and resources, so a local fix needs system-wide appraisal.", "basis": "Foley & Horwitz 2025; systems thinking."}, {"id": "patient", "name": "The patient representative", "role": "Longitudinal lived experience", "short": "What is invisible when care is divided into encounters?", "intro": "The patient experiences continuing symptoms and several service transitions. The investigation must take her narrative seriously without treating it as a substitute for clinical records.", "opening": "Simulated patient statement: “I described the problem repeatedly, but I was never sure who had the full picture or whom I should contact when things changed.” This statement illustrates experience, not proven record failure.", "q": [{"title": "Patient–1 · Interpret experience", "prompt": "What is the strongest systems inference from this account?", "options": [{"text": "Patients need a named care coordinator at all stages of pregnancy.", "feedback": "A coordinator might help but is an intervention before the underlying need is established.", "branch": "Test whether continuity problems are common and what coordination already exists."}, {"text": "The patient’s navigation experience is an important cross-encounter outcome to examine with clinical and operational evidence.", "feedback": "Best: treats patient experience as necessary evidence without assuming causation.", "branch": "Map decision points against what the patient understood at the time."}, {"text": "Every service should provide identical follow-up instructions.", "feedback": "Consistency can help but instructions must reflect clinical and service context.", "branch": "Investigate what was appropriate and communicated, not just uniformity."}, {"text": "A unified record would resolve most of the patient’s uncertainty.", "feedback": "Better information may help but uncertainty also involves relationships, guidance and access.", "branch": "A data solution alone cannot guarantee coordination."}], "correct": 1, "newEvidence": ""}, {"title": "Patient–2 · Set the investigative question", "prompt": "Which question best brings the patient account into a system-level investigation?", "options": [{"text": "What proportion of patients prefer maternity assessment to ED assessment?", "feedback": "Preferences matter but are not the only determinant of clinical appropriateness.", "branch": "Choice alone may not capture changing clinical needs."}, {"text": "How frequently are patients given written instructions on whom to call?", "feedback": "An important process measure but may not reflect understanding or usability.", "branch": "Assess comprehension and subsequent experience."}, {"text": "How do patients with recurrent complex presentations experience navigation, continuity and access, and how do services respond?", "feedback": "Best: connects lived experience to organisational processes and future patients.", "branch": "This is a candidate cross-service learning question."}, {"text": "What explains why this patient sought a private specialist?", "feedback": "This may provide context but is too narrow as the organising LHS question.", "branch": "Return to system-wide navigation and continuity."}], "correct": 2, "newEvidence": "Additional evidence: a longitudinal patient story can connect events that individual departmental records present separately."}], "clue": "The patient’s cross-encounter experience is a distinct evidence source and cannot be reduced to one consultation.", "basis": "Menear et al. 2019; Foley & Horwitz 2025."}], "synthesis": [{"title": "Synthesis–1 · Scope the system", "prompt": "What is the most feasible initial boundary for a cross-service LHS discovery exercise?", "options": [{"text": "Hospital ED alone, so the sponsor has complete operational control.", "feedback": "Feasible internally but excludes clinically meaningful connections with other services.", "branch": "The scope could miss the patient’s longitudinal experience."}, {"text": "All pregnancy-related services across the state.", "feedback": "Broad enough but unlikely to be feasible or necessary for the initial learning question.", "branch": "A wider scope can follow if evidence justifies it."}, {"text": "ED and maternity services with defined primary-care and private-specialist interfaces and partnership requirements.", "feedback": "Best: balances whole-journey relevance with realistic organisational authority.", "branch": "Specify which external agreements are needed."}, {"text": "GP and private obstetric services only, as the earliest encounters set the subsequent pathway.", "feedback": "Early encounters matter but later hospital pathways are also central.", "branch": "Do not assume that earlier events determined later outcomes."}], "correct": 2, "newEvidence": "You can map primary, private and hospital services, but the hospital controls only internal pathways."}, {"title": "Synthesis–2 · Grade the evidence", "prompt": "Which statement is defensible in the first scoping charter?", "options": [{"text": "Information silos caused fragmented care.", "feedback": "This is a causal claim beyond the available evidence.", "branch": "Label it as a testable hypothesis."}, {"text": "The patient had multiple service encounters; information continuity and coordination across interfaces require further evidence.", "feedback": "Best: distinguishes fact and hypothesis and identifies the next data need.", "branch": "The charter should specify how to test the interface questions."}, {"text": "Long ED waits demonstrate system failure, even if decisions were clinically appropriate.", "feedback": "Waits may warrant review but their significance needs context and comparators.", "branch": "Distinguish observed duration from causal explanation."}, {"text": "No system problem can be identified until all medical records are reviewed.", "feedback": "You can scope a credible inquiry while acknowledging missing evidence.", "branch": "An LHS investigation begins with bounded uncertainty."}], "correct": 1, "newEvidence": "Your mapped journey includes some confirmed encounters and several unverified transfers."}], "number": 1, "literature": [{"label": "Foley & Horwitz, Learning Health Systems (2025)", "url": "https://doi.org/10.1017/9781009325912"}, {"label": "Plsek & Greenhalgh, The challenge of complexity (2001)", "url": "https://doi.org/10.1136/bmj.323.7313.625"}], "workshopBridge": "Define patient population, cross-service interfaces, provisional learning problem and controllable boundaries."}, {"title": "The Executive Office", "topic": "Shared purpose and leadership", "subtitle": "Competing service priorities collide. Can leaders commit to one achievable learning aim without deciding the solution in advance?", "lobby": "After repeated presentations and specialist review, senior leaders want a coordinated response. ED, maternity, GPs and patients value different outcomes. The hospital has expressed support but has not allocated resources or agreed who can make cross-service decisions.", "mission": "Distinguish shared purpose, sponsorship, readiness and practical decision authority. Build a learning aim that patients and professionals can defend.", "conclusion": "The first leadership task is to define a shared learning aim and accountable, resourced approach across relevant services. Executive enthusiasm is not sufficient evidence of organisational readiness.", "fields": [["population", "Who and where is the improvement for?", "Population and services involved."], ["learning", "Shared learning aim", "An aim reflecting patient, clinical and operational value."], ["sources", "Competing priorities and evidence", "Whose goals and evidence need reconciling?"], ["quality", "Commitment versus efficacy", "Which readiness claims are demonstrated or unknown?"], ["governance", "Accountable sponsor and decision route", "What can the lead service authorise?"], ["investment", "First leadership decision", "Resources, authority or coalition needed first."]], "refs": ["Foley & Horwitz (2025), Strategy, structure and governance.", "Weiner (2009), A theory of organizational readiness for change.", "Menear et al. (2019), Value-creating learning health systems.", "Bravata et al. (2025), Leading Learning Health Systems."], "witnesses": [{"id": "executive", "name": "The executive sponsor", "role": "Strategic leadership", "short": "What would make this an organisational priority?", "intro": "The hospital executive agrees that recurrent complex pregnancy presentations warrant investigation. One proposal is to reduce ED visits; another is to improve access and coordination.", "opening": "Simulated CEO briefing: “We can fund a modest initial investigation, but I need to know its value, decision authority and what would justify continued investment.”", "q": [{"title": "Executive–1 · Frame value", "prompt": "Which proposed purpose gives the organisation the strongest basis for learning?", "options": [{"text": "Reduce unplanned ED attendances for patients with pregnancy bleeding.", "feedback": "An operational measure may penalise clinically appropriate urgent care.", "branch": "Ask whether fewer visits genuinely means safer or more appropriate care."}, {"text": "Improve safe, coordinated access and continuity for comparable patients, using evidence to identify the most important barriers.", "feedback": "Best: aligns patient and service outcomes while keeping the intervention open.", "branch": "You can identify clinical, experiential and operational measures later."}, {"text": "Develop a unified digital care plan between primary and maternity services.", "feedback": "This is a candidate intervention rather than a shared purpose.", "branch": "First establish whether the need and technology can be justified."}, {"text": "Standardise referral practices across ED, maternity and GP services.", "feedback": "Standardisation may help but not all clinical circumstances warrant identical pathways.", "branch": "Define what outcome standardisation should achieve."}], "correct": 1, "newEvidence": ""}, {"title": "Executive–2 · Confirm readiness", "prompt": "The CEO supports the goal, but no protected time or cross-service decision route has been agreed. What can be concluded?", "options": [{"text": "Readiness is high because strategic endorsement is documented.", "feedback": "Commitment alone does not establish implementation efficacy.", "branch": "The project may stall without authority and workforce capacity."}, {"text": "Readiness is low because the operating model is incomplete.", "feedback": "The incomplete arrangements are gaps, but overall readiness needs systematic assessment.", "branch": "Avoid a categorical judgement before evaluating other capabilities."}, {"text": "Commitment appears plausible, while implementation efficacy, resources and authority remain uncertain.", "feedback": "Best: distinguishes readiness dimensions without claiming a full assessment.", "branch": "Next establish resource availability, task demands and responsible leaders."}, {"text": "A preliminary intervention should demonstrate benefit before resources are allocated.", "feedback": "Small pilots can inform investment but cannot replace basic safeguards or workable capacity.", "branch": "Avoid shifting unsupported costs to frontline staff."}], "correct": 2, "newEvidence": "Additional evidence: executive sponsorship was verbally confirmed, but it did not provide budget, protected staff time or a signed governance mandate."}], "clue": "Shared purpose needs a named, resourced sponsor and a realistic decision pathway.", "basis": "Weiner 2009; Foley & Horwitz 2025."}, {"id": "operations", "name": "The ED operations manager", "role": "Service leadership and capacity", "short": "How do local targets affect the proposed aim?", "intro": "The ED manager wants fewer long waits and lower congestion. They support a coordinated pathway but worry about the impact on staff and competing priorities.", "opening": "Simulated operations dashboard: total ED length of stay varies by day; imaging capacity and specialist consultation affect patient flow. No clinically adjusted maternity-pathway analysis has been completed.", "q": [{"title": "Operations–1 · Choose a useful metric", "prompt": "Which first measure best complements a patient-centred learning aim?", "options": [{"text": "Median ED length of stay for all pregnancy-related attendances.", "feedback": "Useful as a broad operational measure but varies with case-mix and clinical need.", "branch": "Add appropriate subgroup definition and specialist pathway context."}, {"text": "Proportion of pregnant patients discharged within four hours.", "feedback": "A common performance indicator but may conflict with appropriate assessment or monitoring.", "branch": "A speed target should not displace clinical safety."}, {"text": "Time to clinically appropriate assessment across ED and maternity transitions, interpreted with acuity and patient experience.", "feedback": "Best: links access, coordination and clinical context.", "branch": "Define reliable timestamps, eligibility and balancing measures."}, {"text": "Share of presentations redirected immediately to maternity.", "feedback": "May indicate pathway use but not clinical appropriateness or patient benefit.", "branch": "Investigate whether direct maternity assessment is safe and feasible."}], "correct": 2, "newEvidence": ""}, {"title": "Operations–2 · Counter competing priorities", "prompt": "Maternity leaders worry that the ED initiative will move workload into their service. What should leaders do?", "options": [{"text": "Ask ED and maternity to agree a common pathway and shared measures before funding changes.", "feedback": "Best: builds joint purpose and surfaces competing resource implications.", "branch": "Use shared governance to identify costs, workload and safety effects."}, {"text": "Proceed with ED efficiency metrics and provide maternity a separate resource request.", "feedback": "Separates interdependent effects into competing improvement agendas.", "branch": "The system may merely shift work and delay."}, {"text": "Commission a capacity simulation before bringing clinicians together.", "feedback": "Modelling can help, but assumptions and priorities require clinical and operational input.", "branch": "Stakeholders should shape the simulation questions."}, {"text": "Set a whole-hospital target for reducing ED activity and leave departments flexibility.", "feedback": "Shared targets can promote alignment, but could reward clinically inappropriate avoidance.", "branch": "Include patient-centred and balancing outcomes."}], "correct": 0, "newEvidence": "Additional evidence: an ED process change could increase specialist workload at times when maternity capacity is already constrained."}], "clue": "Locally attractive metrics can conflict; alignment requires shared outcomes and attention to displaced work.", "basis": "Foley & Horwitz 2025; Menear et al. 2019."}, {"id": "liaison", "name": "The primary-care liaison", "role": "External partnership and GP interface", "short": "Who can authorise change beyond the hospital?", "intro": "The GP representative supports improving continuity but notes that hospital leaders cannot direct independently operated general practices to change records or workflow.", "opening": "Simulated primary-care liaison: “We could recruit willing practices to co-design the information questions, but we need clarity about workload, data access and the purpose of sharing.”", "q": [{"title": "GP liaison–1 · Build the coalition", "prompt": "Which first partnership proposal is most feasible?", "options": [{"text": "Require all referring GP practices to use a standard maternity template.", "feedback": "An internal hospital mandate may not bind independent practices.", "branch": "Participation and external authority require negotiation."}, {"text": "Start with a small group of willing GP and hospital partners to define the problem, responsibilities and information needs.", "feedback": "Best: establishes a feasible cross-organisational coalition.", "branch": "Later scale depends on evidence of value and appropriate agreements."}, {"text": "Ask the PHN to deliver the initiative on behalf of GPs before the hospital proceeds.", "feedback": "A PHN could help convene partners but does not automatically control clinical workflows.", "branch": "Agree sponsorship and respective responsibilities first."}, {"text": "Limit the LHS to hospital services to avoid cross-organisational complexity.", "feedback": "A hospital-first scope may be possible but could miss essential information and patient transitions.", "branch": "Document the boundary and any residual blind spots."}], "correct": 1, "newEvidence": ""}, {"title": "GP liaison–2 · Establish incentives", "prompt": "GP participation is supported in principle but requires staff time and data review. What is the strongest leadership response?", "options": [{"text": "Provide continuing professional development credit for participation.", "feedback": "Recognition can support engagement but does not guarantee time or workable data arrangements.", "branch": "Consider workload and practice-level costs."}, {"text": "Share hospital reports to demonstrate the benefits and recruit GPs later.", "feedback": "Feedback is valuable, but practices should help determine meaningful questions early.", "branch": "An externally defined aim may not reflect GP priorities."}, {"text": "Agree a proportionate partnership with defined roles, practical resources and return of useful insights to participating practices.", "feedback": "Best: connects value, capacity and mutual accountability.", "branch": "Record how the arrangement will be maintained."}, {"text": "Recruit one enthusiastic GP champion to represent every practice.", "feedback": "A champion helps, but views and capabilities vary across practices.", "branch": "Assess representativeness and ongoing engagement."}], "correct": 2, "newEvidence": "Additional evidence: general practices have separate data custody and operational arrangements; the hospital cannot assume it can mandate changes in their systems."}], "clue": "Cross-organisational leadership needs partnership, mutual value and recognised capacity constraints.", "basis": "GP primer; Foley & Horwitz 2025."}], "synthesis": [{"title": "Synthesis–1 · Finalise a learning aim", "prompt": "Which initial leadership resolution is strongest?", "options": [{"text": "Appoint maternity as the lead service and require ED to report specialist-review delays.", "feedback": "Operationally simple but may define the problem too narrowly.", "branch": "More than one service influences continuity."}, {"text": "Create a cross-service sponsored discovery initiative with a shared patient-centred aim, scope and explicit organisational responsibilities.", "feedback": "Best: aligns purpose and accounts for organisational boundaries.", "branch": "Document who can decide, resource and partner."}, {"text": "Invest in common technology to give the initiative a tangible deliverable.", "feedback": "Prematurely selects a solution before testing the learning question.", "branch": "A technology investment is not itself shared purpose."}, {"text": "Ask patient and staff representatives to agree a priority by voting.", "feedback": "Participation is necessary but governance and evidence remain essential.", "branch": "Voting does not establish feasibility or authority."}], "correct": 1, "newEvidence": "The hospital has executive interest, differing department priorities and an independent primary-care interface."}, {"title": "Synthesis–2 · Readiness verdict", "prompt": "What should the scoping charter state?", "options": [{"text": "The organisation is ready for full implementation, pending staff training.", "feedback": "Unverified authority and resources prevent this conclusion.", "branch": "Training is not a substitute for readiness."}, {"text": "There is no readiness because the GP network is independent.", "feedback": "Cross-sector boundaries create constraints but not categorical impossibility.", "branch": "Partnership mechanisms may be feasible."}, {"text": "Leadership commitment is a provisional strength; implementation efficacy and resources are gaps to assess before intervention selection.", "feedback": "Best: an evidence-calibrated readiness conclusion.", "branch": "Prioritise sponsor mandate, time and partnerships."}, {"text": "Progress should stop until an organisation-wide digital maturity audit is complete.", "feedback": "Digital assessment may contribute but cannot replace targeted readiness work.", "branch": "Match assessment effort to scoped aims."}], "correct": 2, "newEvidence": "Executive support is expressed; protected time, formal responsibility and cross-service agreements remain unresolved."}], "number": 2, "literature": [{"label": "Weiner, Organisational readiness for change (2009)", "url": "https://doi.org/10.1186/1748-5908-4-67"}, {"label": "Bravata et al., Leading Learning Health Systems (2025)", "url": "https://doi.org/10.1007/s11606-025-09849-0"}], "workshopBridge": "Define shared purpose, accountable sponsor, partner commitments, and distinguish commitment from efficacy."}, {"title": "The Learning Community", "topic": "Partnership and co-production", "subtitle": "Different people see different parts of the journey. Who can genuinely shape the learning agenda?", "lobby": "Recurrent presentations raise questions about continuity. The hospital is establishing a learning community. Patient, GP, ED, maternity, allied health, data and operational teams may all hold relevant but incomplete knowledge.", "mission": "Construct a learning community that co-defines questions, integrates perspectives and gives participants genuine influence rather than only consultation.", "conclusion": "The learning community requires appropriate representation, accessible participation, transparent decision rights and practical feedback mechanisms. Diverse testimony matters only when it can change priorities and analyses.", "fields": [["population", "Who is affected and represented?", "Include relevant groups and missing voices."], ["learning", "Shared learning priority", "How did stakeholder input reshape the question?"], ["sources", "Members and distinct knowledge", "Who contributes experiential, clinical, operational and analytical knowledge?"], ["quality", "Potential representation and power gaps", "Who may be absent or unable to influence?"], ["governance", "Decision and feedback rules", "How will input affect decisions?"], ["investment", "First learning-community capability", "What convening and engagement structures are needed?"]], "refs": ["Foley & Horwitz (2025), Learning communities and co-design.", "Menear et al. (2019), Value-creating learning health systems.", "Bravata et al. (2025), VA geriatric learning community.", "Davis et al. (2021), Geisinger patient and family advisory work."], "witnesses": [{"id": "patient", "name": "The patient partner", "role": "Consumer and lived-experience expertise", "short": "Whose outcome matters to the learning question?", "intro": "The patient experienced repeated appointments and unclear routes to further advice. The team has proposed reducing ED presentations as the main outcome.", "opening": "Simulated patient partner: “I would rather present again than miss a serious change. I wanted to know the right place to go and to feel that someone understood the history.”", "q": [{"title": "Patient–1 · Challenge a metric", "prompt": "How should the learning community respond to the proposed repeat-attendance target?", "options": [{"text": "Keep the target but add patient satisfaction as a secondary measure.", "feedback": "Experience is necessary, but fewer attendances may still conflict with appropriate care.", "branch": "Revisit the aim before finalising indicators."}, {"text": "Use patient interviews to identify barriers, then have clinical leaders choose the performance measures.", "feedback": "Interviews supply knowledge but do not guarantee patients influence measures.", "branch": "Representation needs decision influence."}, {"text": "Co-define outcomes that distinguish clinically appropriate care seeking from avoidable navigation difficulties.", "feedback": "Best: integrates patient, clinical and operational value.", "branch": "Reframe success around safety, coordination and experience."}, {"text": "Replace repeat attendance with a patient-reported experience outcome.", "feedback": "Experience is vital but cannot independently capture safety or clinical appropriateness.", "branch": "Combine complementary outcomes."}], "correct": 2, "newEvidence": ""}, {"title": "Patient–2 · Make participation real", "prompt": "The patient partner is invited to review a proposed pathway after the team has already set the learning question. What change is most important?", "options": [{"text": "Give consumer partners input when defining the problem and outcome measures, with accessible materials and transparent decisions.", "feedback": "Best: moves from consultation to influential co-production.", "branch": "Record which contributions changed the investigation."}, {"text": "Add more patient representatives to the final approval meeting.", "feedback": "More representation helps but timing and influence matter.", "branch": "Late involvement still limits priority setting."}, {"text": "Collect additional written patient surveys before finalising the pathway.", "feedback": "More experience data may enrich evidence, but surveys do not replace participation in decisions.", "branch": "Define how responses will be interpreted and acted on."}, {"text": "Invite patients to every clinical discussion involving the pathway.", "feedback": "Patients should be partners but access, privacy and relevance require appropriate participation design.", "branch": "Agree roles, support and boundaries."}], "correct": 0, "newEvidence": "Additional evidence: a consumer representative has attended two meetings but cannot identify how patient input has changed any decisions."}], "clue": "The patient’s contribution must inform the problem, outcome definition and decision-making—not only approve a finished proposal.", "basis": "Menear et al. 2019; Foley & Horwitz 2025."}, {"id": "gp", "name": "The GP representative", "role": "Primary-care and cross-organisational knowledge", "short": "How can independent services participate meaningfully?", "intro": "Hospital clinicians propose a hospital-led group with occasional updates to GPs. Primary care manages longitudinal follow-up outside the hospital.", "opening": "Simulated GP statement: “I can describe discharge communication and community follow-up, but I cannot commit every practice without discussing feasibility and workload.”", "q": [{"title": "GP–1 · Represent continuity", "prompt": "Which membership arrangement best addresses the primary-care interface?", "options": [{"text": "Use one GP champion to advise the team at quarterly meetings.", "feedback": "A champion can help but may not capture broad workflows or influence ongoing decisions.", "branch": "Specify representative selection and responsibilities."}, {"text": "Include a GP/primary-care representative as a core partner with practical support and access to the learning process.", "feedback": "Best: makes longitudinal primary-care knowledge available during scoping.", "branch": "Allow that partner to influence learning priorities and evidence interpretation."}, {"text": "Request electronic reports from participating practices and review them internally.", "feedback": "Data can inform analysis but cannot represent professional knowledge and operational constraints alone.", "branch": "Engagement must go beyond data extraction."}, {"text": "Invite a PHN manager to replace GP participation.", "feedback": "PHNs can support engagement but do not automatically substitute for clinical practice perspectives.", "branch": "Combine network and practice knowledge where appropriate."}], "correct": 1, "newEvidence": ""}, {"title": "GP–2 · Resolve competing explanations", "prompt": "The hospital interprets repeat presentations as poor discharge coordination. The GP suggests persistent symptoms and uncertainty may be contributing. What next?", "options": [{"text": "Treat discharge coordination as the principal hypothesis, then use GP evidence to modify it.", "feedback": "This pre-ranks the hospital explanation without sufficient evidence.", "branch": "Keep multiple explanations open."}, {"text": "Prioritise the GP interpretation as the more longitudinal view.", "feedback": "Primary-care perspective is valuable but not complete or determinative.", "branch": "Integrate with hospital and patient evidence."}, {"text": "Jointly map events, compare evidence for different hypotheses and agree what remains unknown.", "feedback": "Best: supports co-interpretation rather than positional authority.", "branch": "Use the learning community to test assumptions together."}, {"text": "Commission an independent chart review to resolve disagreement.", "feedback": "A review can help but may not address experiential and operational evidence.", "branch": "Determine what records cannot explain."}], "correct": 2, "newEvidence": "Additional evidence: the GP has follow-up and referral context that was not included in the hospital analyst’s initial extract."}], "clue": "Cross-service partnerships require sustained voice and shared interpretation, not just information supplied to the hospital.", "basis": "GP primer; Bravata et al. 2025."}, {"id": "allied", "name": "The social worker", "role": "Allied health and practical patient burdens", "short": "Which information is missed by clinical datasets?", "intro": "The patient reports stress associated with repeated visits, uncertainty and balancing family responsibilities. Social work offers psychosocial support.", "opening": "Simulated social work note: “Travel, work, childcare, language, family support and prior experiences can shape how feasible a pathway is for patients.”", "q": [{"title": "Allied–1 · Expand the learning question", "prompt": "What should the group do with the social work perspective?", "options": [{"text": "Include an optional patient-experience survey after the pathway is designed.", "feedback": "This collects feedback but leaves the initial priority and design unchanged.", "branch": "Investigate burden earlier in the process."}, {"text": "Prioritise psychosocial outcomes over operational waiting-time measures.", "feedback": "Burden matters but should be integrated with safety and service outcomes.", "branch": "Avoid substituting one narrow outcome for another."}, {"text": "Ask social workers to advise on eligibility criteria for coordinated care.", "feedback": "They may add value, but the wider issue is the influence of access and practical burden.", "branch": "Clarify the relevant determinants."}, {"text": "Integrate practical burden and access equity into problem definition, sampling and outcome selection.", "feedback": "Best: prevents systematically excluding less-visible experiences.", "branch": "Specify how these data will influence the investigation."}], "correct": 3, "newEvidence": ""}, {"title": "Allied–2 · Address tokenism", "prompt": "The learning-community meeting runs during clinical hours and uses technical language inaccessible to some consumer participants. What improves co-production?", "options": [{"text": "Provide an accessible briefing, flexible participation and support, with explicit opportunities to shape decisions.", "feedback": "Best: addresses practical inclusion and actual influence.", "branch": "Participation quality improves through accommodation and decision rights."}, {"text": "Invite consumers to send written comments before each meeting.", "feedback": "Useful for accessibility but not sufficient if comments are not considered in decisions.", "branch": "Provide transparent response and involvement."}, {"text": "Appoint the social worker to represent patient priorities at all meetings.", "feedback": "A professional can support consumer engagement but does not replace patient voice.", "branch": "Avoid proxy representation as the default."}, {"text": "Schedule a separate patient forum after the clinical work is complete.", "feedback": "May gather input but risks late or parallel rather than integrated involvement.", "branch": "Invite input early and throughout."}], "correct": 0, "newEvidence": "Additional evidence: a patient who lacks flexible work hours and transport is unlikely to participate through standard weekday in-person meetings."}], "clue": "Equity, practical burden and accessibility must be built into community design and evidence selection.", "basis": "Menear et al. 2019; Geisinger patient partnership."}], "synthesis": [{"title": "Synthesis–1 · Define the community", "prompt": "Which structure most closely supports LHS co-production?", "options": [{"text": "A hospital steering group that solicits feedback from external stakeholders at major milestones.", "feedback": "Consultation is useful, but limits influence over early framing and evidence.", "branch": "Patients and primary-care partners could become peripheral."}, {"text": "A continuing learning community with defined membership, shared priority-setting, accessible participation and traceable decision-making.", "feedback": "Best: supports sustained, meaningful influence and accountability.", "branch": "Document who decides and how stakeholder input changes work."}, {"text": "Separate clinical, patient and data panels that submit recommendations to the executive.", "feedback": "Specialised groups may help but risk re-creating fragmented interpretation.", "branch": "Provide shared synthesis and decision mechanisms."}, {"text": "An open network where any interested staff member can attend meetings.", "feedback": "Open participation may help but does not assure representation, continuity or authority.", "branch": "Specify core roles and manageable operating arrangements."}], "correct": 1, "newEvidence": "The group has patient, primary care, hospital clinical, operational, allied health and analytics perspectives, but influence varies."}, {"title": "Synthesis–2 · Refine the shared problem", "prompt": "Which problem statement is the strongest provisional starting point?", "options": [{"text": "Reduce unnecessary ED visits for patients with recurrent pregnancy complications.", "feedback": "The label unnecessary requires clinical evidence not yet established.", "branch": "Do not define the target from an assumed causal judgement."}, {"text": "Improve communication so patients feel better informed.", "feedback": "Important but restricts a wider coordination and access inquiry.", "branch": "Retain the broader systems question."}, {"text": "Investigate variation in safe access, coordination and patient experience across recurrent complex pregnancy presentations.", "feedback": "Best: focused yet open to multiple system mechanisms and patient-centred outcomes.", "branch": "Turn this into feasible evidence and measures."}, {"text": "Establish direct maternity access for patients with complex symptoms.", "feedback": "Presumes an intervention before verifying eligibility, safety and system causes.", "branch": "Clinical governance and feasibility remain unknown."}], "correct": 2, "newEvidence": "The hospital initially framed repeated ED presentations as the primary problem; stakeholders identify care continuity and access as additional concerns."}], "number": 3, "literature": [{"label": "Menear et al., Value-creating LHS framework (2019)", "url": "https://doi.org/10.1186/s12961-019-0477-3"}, {"label": "Bravata et al., Leading Learning Health Systems (2025)", "url": "https://doi.org/10.1007/s11606-025-09849-0"}], "workshopBridge": "Name essential learning-community members, their influence and how lived experience changes the learning question."}, {"title": "The Review Meeting", "topic": "Learning culture and psychological safety", "subtitle": "The strongest clue may be an assumption. Can the organisation question its own explanations without premature blame?", "lobby": "The improvement group revisits the first antenatal consultation, recurrent bleeding and subsequent presentations. Some participants want to identify individual errors; others highlight uncertainty, communication and workload. The purpose is a fair systems inquiry, not judging whether the loss was preventable.", "mission": "Test explanations and model psychological safety, accountability and feedback while preserving clinical uncertainty.", "conclusion": "A learning culture makes it possible to speak up, examine contradictory evidence and act on concerns with fair accountability. It does not treat all adverse outcomes as preventable or all responsibility as systemic.", "fields": [["population", "Scope of the learning review", "Which encounters and decisions are in scope?"], ["learning", "Evidence-based learning questions", "Reframe premature judgements as testable questions."], ["sources", "Whose accounts matter?", "Clinicians, patient, operations and governance."], ["quality", "Assumptions and contrary evidence", "Which causal claims are unverified?"], ["governance", "Fair review and feedback processes", "How are accountability and safety preserved?"], ["investment", "First learning-culture capability", "How will staff and patients report and learn?"]], "refs": ["Foley & Horwitz (2025), Culture change.", "Edmondson (1999), Psychological safety and learning behavior.", "Bravata et al. (2025), Responsive listening and debriefs."], "witnesses": [{"id": "midwife", "name": "The antenatal midwife", "role": "Clinical uncertainty and communication", "short": "What can be concluded from a single consultation?", "intro": "At the first public antenatal appointment the patient raised continuing spotting and remained dissatisfied with reassurance. You cannot infer how the later outcome could have been predicted from this account alone.", "opening": "Simulated midwife interview: “I would want to know how follow-up was arranged, what information we had and how staff are supported to communicate uncertainty.”", "q": [{"title": "Midwife–1 · Analyse the concern", "prompt": "Which review question best avoids hindsight bias without dismissing the patient?", "options": [{"text": "Would a different midwife have recognised the risks earlier?", "feedback": "A professional review may be relevant, but this presupposes a discoverable early signal.", "branch": "First examine available evidence and applicable standards."}, {"text": "How were symptoms, uncertainty, patient concerns and follow-up responsibilities assessed and communicated?", "feedback": "Best: produces testable system and practice questions.", "branch": "Separate record evidence from retrospective inference."}, {"text": "Should all patients with ongoing spotting receive specialist escalation?", "feedback": "This assumes a clinical policy change without evidence of benefit or safety.", "branch": "Clinical criteria require specialist review."}, {"text": "Why was the patient not reassured sufficiently by the consultation?", "feedback": "Focuses on perception without fully addressing clinical processes and follow-up.", "branch": "Include the patient’s account and care context."}], "correct": 1, "newEvidence": ""}, {"title": "Midwife–2 · Support speaking up", "prompt": "A midwife is reluctant to report unclear follow-up responsibilities because colleagues may interpret it as blame. What is the best response?", "options": [{"text": "Use anonymous reporting only until the organisation can assure all staff there will be no disciplinary consequences.", "feedback": "Anonymous reporting helps some disclosures but cannot promise exemption from accountability.", "branch": "Make processes fair and transparent."}, {"text": "Refer all discussion to the formal clinical review team and prevent informal reflection.", "feedback": "Formal review can matter but should not block appropriate systems learning.", "branch": "Maintain safe local feedback opportunities."}, {"text": "Offer a facilitated review with clear scope, respectful challenge, protection from inappropriate blame and appropriate escalation of safety concerns.", "feedback": "Best: combines psychological safety and accountability.", "branch": "Report back on findings and changes."}, {"text": "Remind staff of existing policies and require everyone to sign attendance at a training session.", "feedback": "Policy adherence may matter but does not create an environment for honest inquiry.", "branch": "Address workload, uncertainty and leadership response."}], "correct": 2, "newEvidence": "Additional evidence: the written note records the encounter but does not show how the patient understood follow-up advice or what happened outside the consultation."}], "clue": "Learning requires careful handling of uncertainty and feedback, not the assumption that later harm proves earlier error.", "basis": "Foley & Horwitz 2025; Edmondson 1999."}, {"id": "ed", "name": "The ED doctor", "role": "Acute clinical decisions and contextual constraints", "short": "Can a review avoid both blame and complacency?", "intro": "The patient re-presented with changing symptoms. Assessments occurred under different clinical and operational conditions. Clinicians are worried that the review may judge past decisions using information known only later.", "opening": "Simulated ED statement: “I want the timeline reconstructed as it was known at each visit, including clinical status, resource availability and specialist advice.”", "q": [{"title": "ED–1 · Handle hindsight", "prompt": "How should the clinical timeline be reviewed?", "options": [{"text": "Use the complete eventual clinical outcome to judge whether earlier decisions were reasonable.", "feedback": "Retrospective outcomes can motivate review but are not the same as contemporaneous information.", "branch": "Risk of hindsight bias is substantial."}, {"text": "Exclude individual clinical decisions and review only organisational arrangements.", "feedback": "This creates a false divide; both practice and context may warrant examination.", "branch": "Use appropriate clinical review and systems analysis together."}, {"text": "Reconstruct available information, decisions, guidelines and constraints at each point, then examine wider interdependencies.", "feedback": "Best: preserves context while allowing fair assessment.", "branch": "Record what was knowable then and what was learned later."}, {"text": "Ask an independent reviewer to decide which encounter had the strongest warning signs.", "feedback": "Independent clinical review may help, but ranking hindsight signs alone is not sufficient.", "branch": "Combine contemporary record, pathway and contextual evidence."}], "correct": 2, "newEvidence": ""}, {"title": "ED–2 · Move from concern to learning", "prompt": "Staff describe repeated delays obtaining specialist advice. What process best demonstrates a learning culture?", "options": [{"text": "Record the concern, examine its frequency and causes, assign an owner and report back what was learned or changed.", "feedback": "Best: creates a closed feedback process.", "branch": "Visible follow-up builds trust and future reporting."}, {"text": "Escalate every delay to the incident system for individual case review.", "feedback": "Some events require incident reporting, but blanket case-by-case processing may not reveal patterns.", "branch": "Add system-level aggregation and learning."}, {"text": "Provide a new escalation flowchart and require staff to acknowledge it.", "feedback": "A flowchart may help, but only if the cause and feasibility are established.", "branch": "Do not assume information deficit."}, {"text": "Survey staff about delays and publish results at the end of the year.", "feedback": "Feedback is useful but delayed reporting without action weakens learning.", "branch": "Establish responsibility and timely follow-up."}], "correct": 0, "newEvidence": "Additional evidence: some delays are associated with resource constraints rather than knowledge of the escalation process."}], "clue": "Use contemporaneous evidence and close the reporting-to-action loop rather than defaulting to blame or retraining.", "basis": "Foley & Horwitz 2025; organisational learning."}, {"id": "safety", "name": "The quality and safety lead", "role": "Accountability and organisational learning", "short": "Where does formal review meet continuous improvement?", "intro": "The organisation has incident reporting and clinical governance arrangements, but staff say they rarely see how reported concerns influence service design.", "opening": "Simulated governance audit: individual incidents are reviewed, yet cross-service patterns are not routinely discussed with GP partners and patients.", "q": [{"title": "Safety–1 · Connect review systems", "prompt": "What is the best initial improvement in the organisation’s learning process?", "options": [{"text": "Create a new anonymous portal for all staff concerns.", "feedback": "A new channel may help but does not solve the absence of synthesis and feedback.", "branch": "Existing reports still need review and action."}, {"text": "Link appropriate incident, experience and operational reviews to a cross-service learning forum with documented decisions and feedback.", "feedback": "Best: builds collective learning on existing structures.", "branch": "Clarify confidentiality and decision authority."}, {"text": "Transfer all incident investigation responsibility to the LHS team.", "feedback": "This may blur statutory and professional governance responsibilities.", "branch": "Maintain formal review obligations."}, {"text": "Produce quarterly dashboards of reported incidents to compare departments.", "feedback": "Reporting is useful but raw counts risk misinterpretation and lack action pathways.", "branch": "Add context, interpretation and learning."}], "correct": 1, "newEvidence": ""}, {"title": "Safety–2 · Preserve accountability", "prompt": "A reviewer identifies a possible serious care concern requiring formal investigation. What should the learning community do?", "options": [{"text": "Suspend all LHS activities until formal review is complete.", "feedback": "Some activities may need restriction, but system learning can often proceed with safeguards.", "branch": "Coordinate and protect evidence."}, {"text": "Focus only on cultural factors to avoid blaming clinicians.", "feedback": "Could neglect necessary safety and professional responsibilities.", "branch": "A just approach includes accountability."}, {"text": "Discuss the concern openly with the full learning community to demonstrate transparency.", "feedback": "Privacy, procedural fairness and confidential investigation matter.", "branch": "Use appropriate protected channels."}, {"text": "Refer the matter through established clinical governance processes, coordinate boundaries and continue appropriate system learning.", "feedback": "Best: respects formal accountability without abandoning systems improvement.", "branch": "Define what may be shared and when."}], "correct": 3, "newEvidence": "Additional evidence: the hospital has a formal process for clinical concerns but no established method for feeding broader learning back to partner services."}], "clue": "A mature learning culture works alongside, rather than replacing, clinical governance and fair review.", "basis": "Foley & Horwitz 2025; Edmondson 1999."}], "synthesis": [{"title": "Synthesis–1 · Reframe an allegation", "prompt": "Which revised question is strongest?", "options": [{"text": "Why were clinicians unable to recognise the patient’s deterioration sooner?", "feedback": "Assumes earlier recognition was possible and warranted.", "branch": "Examine clinical information chronologically before drawing conclusions."}, {"text": "How did clinical need, discharge arrangements, follow-up information and access pathways interact across recurrent presentations?", "feedback": "Best: open, testable and system-oriented.", "branch": "Specify evidence for each possible mechanism."}, {"text": "How could ED discharge documentation be improved to prevent return visits?", "feedback": "Presumes the appropriate intervention and outcome.", "branch": "Some return visits are clinically necessary."}, {"text": "Were individual staff communicating according to hospital policy?", "feedback": "May be relevant, but restricts the broader investigation.", "branch": "Patient experience and operational conditions also matter."}], "correct": 1, "newEvidence": "A note states: “The patient repeatedly presented because the system kept sending her home.” The chronology confirms presentations but not this causal explanation."}, {"title": "Synthesis–2 · Identify the cultural capability", "prompt": "What capability would most strengthen organisational learning?", "options": [{"text": "A feedback process linking reporting, multidisciplinary interpretation, accountable action and communication of findings.", "feedback": "Best: creates a repeatable learning mechanism.", "branch": "Define responsibility, privacy protections and follow-up cadence."}, {"text": "Additional mandatory staff reporting training.", "feedback": "Useful only if under-reporting is caused by knowledge gaps.", "branch": "Reporting without visible action may not help."}, {"text": "A single hospital-wide incident reporting form.", "feedback": "Standardisation helps capture but not interpretation or action.", "branch": "The problem is the feedback mechanism."}, {"text": "Annual publication of improvement priorities for each department.", "feedback": "Transparency may help but cross-service learning needs ongoing decisions.", "branch": "Turn findings into accountable action."}], "correct": 0, "newEvidence": "Clinical review occurs, but frontline concerns are not consistently synthesised or fed back across services."}], "number": 4, "literature": [{"label": "Foley & Horwitz, Learning Health Systems (2025)", "url": "https://doi.org/10.1017/9781009325912"}, {"label": "Edmondson, Psychological safety and learning (1999)", "url": "https://doi.org/10.2307/2666999"}], "workshopBridge": "Set up fair, psychologically safe review, challenges to assumptions and feedback into practice."}, {"witnesses": [{"id": "gp", "name": "The GP", "role": "Primary care / data custodian", "short": "What was recorded, exchanged and available?", "intro": "The patient's GP arranged early imaging and later referred her to a private obstetrician. The practice holds its own longitudinal record, while the hospital holds different records. You are investigating how information crosses these boundaries—not assuming that a handover failed.", "opening": "The GP explains that consultation notes, test results and correspondence are held in the practice clinical information system. Referrals and letters may be exchanged as documents; a receiving hospital does not automatically have a complete copy of the GP record.", "q": [{"title": "Decision GP–1 · Trace the information", "prompt": "The LHS team wants to establish whether information from primary care could support a longitudinal analysis. What is the strongest first investigative step?", "options": [{"text": "Request a de-identified extract of all pregnancy-related GP encounters from participating practices and reconcile it with hospital ED records.", "feedback": "A multi-practice extract may eventually be valuable, but its feasibility, lawful basis, data definitions and linkage quality are not yet established. It is premature to assume a common extract can be produced.", "branch": "Your extract request reveals that practices use different software configurations and that the sharing arrangements require clarification. The challenge is not solely obtaining more records."}, {"text": "Trace a small, appropriately authorised sample of the key referrals, reports and discharge correspondence, documenting custodians, transfer routes, accessibility and intended analytical use.", "feedback": "This creates an evidence-based map of where data originate, how they move, whether they can be accessed and what governance is needed. It makes later extraction requirements more defensible.", "branch": "The sample trace establishes a distinction between what a service generated, transmitted, could access and could analyse. These are different data capabilities."}, {"text": "Use My Health Record as the shared longitudinal source and assess whether the hospital analytics team can access the relevant documents.", "feedback": "My Health Record can contain selected shared documents, but is not the complete GP record and does not confirm that material was reviewed or is available as structured research data.", "branch": "The record may display summaries or reports, but it cannot be assumed to represent every consultation, symptom description or care decision."}, {"text": "Start with Medicare and ED administrative data to identify cross-sector visits, and defer clinical documentation until later.", "feedback": "Administrative data can help describe service use, but usually lacks the clinical and experiential context needed to interpret why a patient sought care and how services coordinated.", "branch": "Utilisation records identify encounters, but the meaning of repeated attendance remains unclear without clinical and patient context."}], "correct": 1, "newEvidence": ""}, {"title": "GP–2 · Exchange is not analysis", "prompt": "An informatics lead says that adopting HL7 FHIR will make GP and hospital data ready for comparative analysis. What is the most defensible response?", "options": [{"text": "FHIR can substantially improve structured exchange; first investigate whether the existing referral messages can provide the needed variables.", "feedback": "Document transfer and FHIR exchange may help, but availability, meaning and reuse require separate checks.", "branch": "The team improves exchange while leaving cohort definitions and analytical governance unresolved."}, {"text": "Apply a common analytical data model such as OMOP to the hospital extract, then determine which GP fields are still unavailable.", "feedback": "A common data model can improve comparability but does not automatically create access rights, reliable linkage or clinically meaningful data.", "branch": "Analytical standardisation proceeds before the partner agreements and evidence needs are established."}, {"text": "Begin with hospital-level aggregate indicators while planning FHIR integration; do not depend on cross-service patient-level data yet.", "feedback": "This may be a reasonable bounded interim approach, but it may not answer the longitudinal question or assess which information is essential.", "branch": "A fast descriptive report risks becoming the de facto problem definition."}, {"text": "Distinguish exchange, analytical harmonisation and use: establish information needs, access, quality, provenance and clinical validation before selecting technical standards.", "feedback": "Best-supported: FHIR and common data models address different technical tasks; neither establishes fitness for purpose, permission or clinical meaning.", "branch": "A bounded requirements and governance assessment identifies which technology—if any—must change first."}], "correct": 3, "newEvidence": "Further evidence: structured GP-to-hospital exchange, a common data model and approved secondary use are different technical and governance capabilities. My Health Record is not a complete copy of the GP record."}], "clue": "Primary-care records are held separately. Document transfer, clinical availability and computable data are different stages; each must be verified.", "basis": "GP_in_Australia_Primer.docx, pp. 1, 4–5; LHS sprint content.docx, Topic 5."}, {"id": "analyst", "name": "The Hospital Analyst", "role": "Health service / analytics", "short": "Can routine data answer the learning question?", "intro": "The hospital has ED, imaging, outpatient and maternity datasets. These are useful for operational monitoring, but the LHS team wants to understand clinically comparable patient journeys, not simply count visits.", "opening": "The analyst can identify ED arrival and departure times, triage categories, coded diagnoses and some imaging events. The extract is less reliable at linking outpatient follow-up and correspondence from external providers.", "q": [{"title": "Decision AN–1 · Define a meaningful cohort", "prompt": "Which approach gives the strongest initial basis for investigating recurrent complex maternity presentations?", "options": [{"text": "Define recurrent attendance as three or more ED encounters and compare waiting times for these patients with all other presentations.", "feedback": "This is reproducible and could describe a high-utilisation subgroup, but it may combine very different clinical situations and cannot establish whether attendance was avoidable.", "branch": "The count is consistent, but clinicians question whether the selected patients share the same clinical needs or access barriers."}, {"text": "Co-develop clinically justified inclusion criteria with ED and maternity clinicians, then test the consistency, completeness and provenance of candidate data fields.", "feedback": "Correct. A clinically meaningful cohort and a validated data dictionary are prerequisites for interpretable findings. They should also account for patient selection and missing information.", "branch": "The clinical team identifies encounters that look similar administratively but differ in urgency, gestation, symptoms and service need."}, {"text": "Use diagnostic and ultrasound codes to identify patients with documented complications, then examine their subsequent service use.", "feedback": "This could identify a clinically relevant subgroup, but coding practices and investigations may vary; the codes alone need validation and may miss patients without a recorded diagnosis.", "branch": "The cohort changes substantially depending on which code list is used. A definition may be reproducible without being clinically valid."}, {"text": "Conduct a qualitative audit of a small sample of complex ED records before defining a quantitative cohort.", "feedback": "A focused audit can inform cohort design, but should be paired with a plan for systematic selection and cross-service representativeness rather than becoming the sole definition.", "branch": "Narrative review reveals clinical complexity but creates new questions about whose encounters were selected and which records are missing."}], "correct": 1, "newEvidence": ""}, {"title": "Analyst–2 · External evidence arrives", "prompt": "A clinical librarian identifies a recent review of care navigation interventions, but its studies are mainly from urban centres. Hospital data can count repeat ED presentations, while patient experience suggests some returns are clinically necessary. What should the team do?", "options": [{"text": "Use the external review to shortlist intervention components, then select whichever is easiest to pilot locally.", "feedback": "Shortlisting options may be useful later, but transferability and the local problem have not yet been assessed.", "branch": "The team risks selecting a credible intervention for the wrong local mechanism."}, {"text": "First validate the local repeat-attendance measure and obtain a representative sample before considering published findings.", "feedback": "Data validation and sampling matter, but delaying external evidence appraisal discards knowledge that could refine the local study.", "branch": "Local analysis proceeds without using published research to identify what is already known."}, {"text": "Critically appraise the review’s quality and applicability, triangulate it with local data and patient accounts, and record remaining uncertainties before selecting further research or action.", "feedback": "Best-supported: the LHS combines external research, local data and experiential evidence to determine which conclusions are transferable and which gaps need investigation.", "branch": "The learning community refines its question and evidence requirements without assuming a pathway is indicated."}, {"text": "Commission a new Australian systematic review because international service arrangements may differ materially.", "feedback": "An Australian-focused synthesis may be warranted if an important gap remains, but first assess existing syntheses and the local context to avoid duplication.", "branch": "A resource-intensive review is launched before confirming the unanswered question."}], "correct": 2, "newEvidence": "Additional clue: the research librarian confirms that the organisation has database subscriptions but no routine process for surveillance, synthesis, version review or feeding new evidence into policy decisions."}], "clue": "An analysable file is not automatically a valid dataset. Cohort definitions, measurement consistency, clinical context and missingness determine fitness for purpose.", "basis": "LHS sprint content.docx, Topic 5; Foley & Horwitz (2025), data infrastructure and knowledge generation."}, {"id": "patient", "name": "The Patient Representative", "role": "Lived experience / equity", "short": "What do the clinical records fail to capture?", "intro": "The patient describes having to explain her evolving history across services, uncertainty about where to seek help, and the burden of repeated urgent-care encounters. These experiences may be difficult to reconstruct from routine hospital data.", "opening": "The learning community initially proposes reducing repeat ED presentations as its success measure. A patient representative challenges this: some repeat presentations may be clinically necessary. The organisation needs a more defensible learning outcome.", "q": [{"title": "Decision PT–1 · What matters to patients?", "prompt": "Which measure set best captures the intended improvement without assuming that fewer emergency encounters are inherently safer?", "options": [{"text": "Number of ED re-presentations and average time spent in ED, adjusted for triage category.", "feedback": "These may measure service activity, but not whether repeat assessment was clinically appropriate or whether patients understood their care arrangements.", "branch": "A falling re-presentation count could reflect better coordination—or reduced willingness or ability to seek necessary care."}, {"text": "Patient-reported satisfaction with ED and maternity services after each attendance.", "feedback": "Experience surveys can inform improvement, but global satisfaction can miss continuity, navigation, urgency and whether follow-up was appropriate.", "branch": "The score improves while some patients continue to report uncertainty about whom to contact."}, {"text": "Whether a documented care plan exists and how frequently clinicians use the pathway.", "feedback": "These are useful implementation measures, but documentation and pathway use do not necessarily mean patients experienced clearer, safer care.", "branch": "The system can record compliance without showing whether the care arrangement was understandable to patients."}, {"text": "Patient understanding of whom to contact and perceived continuity, alongside clinically appropriate access, safety and service-use indicators.", "feedback": "Correct. This balances patient experience with clinical appropriateness and system outcomes; patient-reported data must be gathered ethically and interpreted for representativeness.", "branch": "The patient narrative now informs what success means, rather than merely adding another comment to a service dashboard."}], "correct": 3, "newEvidence": ""}, {"title": "Decision PT–2 · Who is missing from the evidence?", "newEvidence": "SIMULATED CLUE: Experience feedback is collected mainly through English-language SMS surveys after ED discharge. Participation is voluntary, and the organisation does not know whether respondents represent people with complex journeys, language barriers or pregnancy loss.", "prompt": "How should the learning team strengthen the patient-evidence component of its investigation?", "options": [{"text": "Increase SMS reminders to improve response rates, then weight responses by age and presentation frequency.", "feedback": "Reminders and weighting might help but do not necessarily reach people excluded by language, access or emotional burden. Some selection mechanisms cannot be fixed statistically without suitable data.", "branch": "Response improves among existing recipients while some less visible patient groups remain underrepresented."}, {"text": "Co-design accessible, trauma-informed ways of gathering experience, examine who is missing, and triangulate findings with clinical and operational evidence.", "feedback": "Correct. Patient evidence should be actively and ethically gathered across relevant groups. Its limitations should be documented rather than obscured by a single satisfaction measure.", "branch": "Your evidence plan now includes meaningful consumer participation, sampling considerations and safeguards for sensitive experiences."}, {"text": "Use existing formal complaints and patient liaison records because these capture the most consequential service failures.", "feedback": "Complaints can identify serious concerns but are highly selective and do not represent all experiences; many patients never complain or cannot readily do so.", "branch": "The strongest recorded complaints dominate the story, but the prevalence and distribution of navigation problems remain unknown."}, {"text": "Ask clinical teams to identify patients likely to have experienced poor coordination and conduct interviews with them.", "feedback": "Clinician identification can inform purposive sampling but may omit patients whose difficulties were not visible to professionals; consent and support also need attention.", "branch": "The sample is information-rich but systematically reflects which patients clinicians remember."}], "correct": 1}], "clue": "Patient-generated evidence identifies aspects of care not captured by encounter counts. Sampling, accessibility, sensitivity and triangulation determine how safely and fairly it can inform learning.", "basis": "LHS sprint content.docx, Topics 3, 5 and 7; Menear et al. (2019) patient partnership and equity."}], "synthesis": [{"title": "Synthesis–1 · Foundations and feedback", "prompt": "The hospital has electronic records and a dashboard, but no validated cross-service cohort or standing process for reviewing findings with stakeholders. Which first investment best strengthens its LHS learning utility?", "options": [{"text": "Improve interoperability and build a linked warehouse first, then create a learning community once sufficient data accumulate.", "feedback": "Connectivity might be important, but technical investment alone would not establish clinically meaningful questions or decisions.", "branch": "A larger data platform becomes the initiative before its learning purpose has been agreed."}, {"text": "Establish a bounded, governed data-feasibility effort alongside a resourced learning community and an explicit evidence-review and feedback process.", "feedback": "Best-supported: it joins the technical foundation, the machinery of feedback and the enabling organisational environment without presupposing a large platform.", "branch": "The organisation can test whether it has sufficient evidence and capabilities before scaling investment."}, {"text": "Establish an executive-sponsored evidence-synthesis committee to review published interventions and issue recommendations.", "feedback": "External evidence is essential but a committee without local data validation or operational feedback would still be incomplete.", "branch": "The organisation generates recommendations without reliable mechanisms to test local feasibility."}, {"text": "Build a more clinically informative dashboard that incorporates acuity, imaging and referral measures before recruiting other partners.", "feedback": "Better measures could improve reporting, but the missing decision rights, cross-service meaning and feedback mechanism remain.", "branch": "The new reporting interface risks substituting visibility for learning."}], "correct": 1, "newEvidence": "Synthesis evidence: the GP holds longitudinal primary-care records, the analyst reports uncertain cohort validity and the patient identifies important experience not captured in encounter counts. External reviews can inform—but not replace—local learning."}, {"title": "Synthesis–2 · What knowledge can we claim?", "prompt": "The proposed LHS investigation must combine routine hospital data, primary-care information, published research and lived experience. Which conclusion should appear in the initial scoping charter?", "options": [{"text": "Repeat presentations indicate a probable continuity gap; the organisation should validate this using follow-up surveys and record linkage.", "feedback": "Repeated encounters may be clinically necessary, and no causal gap is yet established. The claim is prematurely directional.", "branch": "The charter treats a possible mechanism as the finding to confirm."}, {"text": "Existing published evidence can determine the most effective coordination pathway, while hospital data are primarily needed to monitor adoption.", "feedback": "Published evidence may not transfer to local populations or resources; the local learning question remains to be characterised.", "branch": "The team shifts too quickly from research findings to implementation."}, {"text": "The hospital should avoid broader analysis until full primary-care data linkage is approved and complete.", "feedback": "A bounded, lawful investigation can begin with existing information and stakeholder co-definition; a complete combined database is not always required.", "branch": "Feasible preliminary learning is delayed unnecessarily."}, {"text": "Current information supports a provisional learning question but cannot establish the cause, frequency or preventability of fragmentation. Data feasibility, research synthesis and patient perspectives should be assessed together.", "feedback": "Best-supported: a defensible charter differentiates a plausible system question from established facts and integrates all three evidence streams.", "branch": "The learning team can determine a proportionate scope and evidence requirements without overclaiming."}], "correct": 3, "newEvidence": "Concluding evidence: existing data describe parts of the journey, published literature may inform mechanisms, and patient accounts reveal values missing from routine administrative measures."}], "number": 5, "title": "The Data Archive", "topic": "Data and evidence capability", "subtitle": "Data quality, interoperability, evidence surveillance and learning infrastructure", "lobby": "The team wants to understand whether this patient journey signals a wider care coordination issue. Records sit across general practice, private specialist and hospital services. Local datasets, published research and patient experience are all potentially valuable but incomplete.", "mission": "Decide which information is fit for purpose, what evidence must be integrated, and what data and learning infrastructure is required before intervention selection.", "conclusion": "A data warehouse is not itself a learning system. The organisation needs governed access, validated definitions, meaningful patient and external evidence, a learning community and repeated feedback into decisions.", "fields": [["population", "Target population and analytical boundary", "Define a meaningful and feasible cohort."], ["learning", "Data and evidence learning question", "What needs to be understood before an intervention?"], ["sources", "Data and evidence sources", "GP records, hospital systems, patient experience, existing research and evidence surveillance."], ["quality", "Validity, completeness and applicability", "What is known versus missing or unverified?"], ["governance", "Data access and research governance", "Custodians, linkage approvals, safeguards, analytical roles."], ["investment", "First data/learning infrastructure priority", "What foundational and feedback capabilities are most needed?"]], "refs": ["Foley & Horwitz (2025) Learning Health Systems", "Steel et al. (2025) LHS strategies in the AI era", "Bian et al. (2026) Learning utility", "Lane et al. (2026) LHS supporting pillars; evidence surveillance and synthesis", "GP in Australia primer"], "literature": [{"label": "Lane et al., LHS evidence surveillance and synthesis (2026)", "url": "https://doi.org/10.1186/s13012-025-01482-z"}, {"label": "Bian et al., Learning utility (2026)", "url": "https://doi.org/10.1038/s44401-026-00107-x"}, {"label": "Foley & Horwitz, Learning Health Systems (2025)", "url": "https://doi.org/10.1017/9781009325912"}], "workshopBridge": "Identify core data sources and evidence surveillance capability, fitness for purpose, provenance, and the missing feedback machinery."}, {"title": "The Specialist Clinic", "topic": "Workforce capability and readiness", "subtitle": "A promising individual adaptation appears. Can the organisation make coordination reliable without relying on one champion?", "lobby": "At approximately 18 weeks, a specialist and midwife arrange an individualised pathway for direct birth-suite access when appropriate. The learning team now considers how such responsiveness could be supported reliably for comparable patients.", "mission": "Separate skills from roles, time, authority, collaboration and support. Scope a capable interprofessional workforce rather than defaulting to training.", "conclusion": "Workforce readiness is a combination of relevant competence, motivation, opportunity, role clarity and organisational support. An individual workaround becomes a reliable capability only with resources and governance.", "fields": [["population", "Which staff and interfaces are in scope?", "Maternity, ED, GP, allied health, data and operations."], ["learning", "Target workforce behaviour or capability", "What must teams be able to do differently?"], ["sources", "Existing expertise and gaps", "Who currently has which competencies and opportunities?"], ["quality", "Constraints beyond training", "Time, authority, workflow, data access and staffing."], ["governance", "Roles and decision responsibility", "Who owns coordination and escalation?"], ["investment", "Priority workforce capability investment", "What support can be sustainably established first?"]], "refs": ["McDonald et al. (2022), Identifying requisite LHS competencies.", "Foley & Horwitz (2025), Workforce development.", "Bian et al. (2026), Learning utility and translation roles.", "Australian Digital Health Capability Framework.", "Henry et al. (2022) TREWS adoption and clinician interaction; https://doi.org/10.1038/s41591-022-01895-z", "Adams et al. (2022) prospective TREWS study; https://doi.org/10.1038/s41591-022-01894-0"], "witnesses": [{"id": "midwife", "name": "The maternity midwife", "role": "Maternity team and clinical coordination", "short": "Can an individual workaround become routine?", "intro": "The specialist and midwife arranged a direct-access plan for an individual patient, but generalising such an arrangement requires clinical criteria, safety processes and available capacity.", "opening": "Simulated staff statement: “The plan helped clarify what to do for this patient. On other shifts, staff may not know whether the arrangement applies or who can authorise it.”", "q": [{"title": "Midwife–1 · Identify the gap", "prompt": "Which workforce readiness issue is most directly indicated?", "options": [{"text": "Staff lack knowledge of the benefits of coordinated care.", "feedback": "They already value coordination; the gap concerns responsibilities and feasibility.", "branch": "A generic awareness course would not solve it."}, {"text": "The service has insufficient specialist staff to run any new pathway.", "feedback": "Capacity might be constrained, but insufficiency has not been established.", "branch": "Measure workload and coverage first."}, {"text": "Roles, eligibility authority and communication across shifts are not reliably defined.", "feedback": "Best: matches the evidence without assuming staffing or attitude problems.", "branch": "Map decisions and handovers."}, {"text": "The hospital needs a dedicated maternity coordinator for every patient.", "feedback": "A role may help but its necessity and cost are unproven.", "branch": "Assess work requirements and alternatives."}], "correct": 2, "newEvidence": ""}, {"title": "Midwife–2 · Build a response", "prompt": "Which first improvement would best address this readiness gap?", "options": [{"text": "Agree clinical eligibility and escalation roles, test workflow scenarios with shifts, and resource the required responsibilities.", "feedback": "Best: defines safe practice and opportunity to perform it.", "branch": "Use scenario feedback to refine procedures."}, {"text": "Create a one-hour online module on the access criteria and issue completion certificates.", "feedback": "Training supports knowledge but not authority, rostering or workflow.", "branch": "Pair training with operational arrangements."}, {"text": "Have the specialist who devised the pathway supervise all early cases.", "feedback": "Short-term mentorship may help but dependence on one person reduces sustainment.", "branch": "Design coverage beyond the original champion."}, {"text": "Make the plan visible in the EMR and audit its acknowledgement.", "feedback": "Visibility is useful but cannot assure appropriate action or capacity.", "branch": "Specify who acts and when."}], "correct": 0, "newEvidence": "Additional evidence: staff report variable after-hours specialist availability and concern about expanding coordination tasks within current rostering."}], "clue": "Readiness needs clear roles and capacity, not simply knowledge or goodwill.", "basis": "McDonald et al. 2022; Foley & Horwitz 2025."}, {"id": "gp", "name": "The GP liaison", "role": "Community workforce and cross-sector continuity", "short": "Can hospital workflows be supported outside hospital?", "intro": "The new access plan is a hospital adaptation, while the GP may continue to receive symptom updates and provide longitudinal support. The practice is organisationally independent.", "opening": "Simulated GP interview: “The plan needs to be understandable outside the hospital; I need to know where to direct a patient and whom to contact for clarification.”", "q": [{"title": "GP–1 · Define a role", "prompt": "What is the strongest primary-care workforce consideration?", "options": [{"text": "GPs should routinely triage all recurrent symptoms before patients contact maternity services.", "feedback": "This may delay clinically necessary urgent assessment and misassign responsibility.", "branch": "Define safe escalation with maternity oversight."}, {"text": "Hospital staff should take exclusive responsibility after a patient reaches high-risk care.", "feedback": "Specialist care is important but primary care may retain relevant coordination roles.", "branch": "Clarify rather than assume boundaries."}, {"text": "Primary care needs accessible guidance, clear contact routes and defined responsibilities for longitudinal follow-up.", "feedback": "Best: supports appropriate shared working without prescribing clinical decisions.", "branch": "Specify transmission and updating of the plan."}, {"text": "Every GP practice should nominate a trained maternity champion.", "feedback": "May support some practices but is a large, untested workforce requirement.", "branch": "Start with feasible partnership arrangements."}], "correct": 2, "newEvidence": ""}, {"title": "GP–2 · Address real capability", "prompt": "Practices support participation but struggle to allocate time for shared improvement meetings. What is the strongest readiness response?", "options": [{"text": "Provide evening webinars on the LHS process.", "feedback": "Flexible education may help but does not directly support collaborative work time.", "branch": "Consider remuneration and practical scheduling."}, {"text": "Negotiate realistic participation, defined deliverables, time support and meaningful return of findings to practices.", "feedback": "Best: aligns motivation and opportunity with organisational context.", "branch": "Make the contribution feasible and worthwhile."}, {"text": "Invite a PHN officer to represent all primary care views without GP attendance.", "feedback": "PHNs can facilitate but may not reflect direct practice experience fully.", "branch": "Balance network coordination and clinical representation."}, {"text": "Use written consultation only and avoid cross-sector meetings.", "feedback": "Written input can help but may limit shared interpretation and adaptation.", "branch": "Combine formats rather than eliminate dialogue."}], "correct": 1, "newEvidence": "Additional evidence: the hospital cannot allocate GP staff time unilaterally; partnership and agreed resources are required."}], "clue": "Primary-care readiness requires feasible participation and mutual clarity across independent organisations.", "basis": "GP primer; Weiner 2009."}, {"id": "translator", "name": "The improvement and data lead", "role": "Interdisciplinary evidence translation", "short": "Who bridges analytical findings and clinical change?", "intro": "The organisation has clinical expertise and analysts, but little protected time to define cohorts, validate measures or translate findings into workflow changes.", "opening": "Simulated analyst: “I can produce datasets, but I need clinicians and patients to explain what an indicator means and an operational owner to act on results.”", "q": [{"title": "Translation–1 · A lesson from AI sepsis detection", "prompt": "In the published TREWS sepsis-alert studies, clinical response depended on clinicians interpreting alerts within workflows. Here, hospital analysts can produce maternity activity reports but clinicians lack protected time to validate and act on them. Which readiness investment addresses the most immediate gap?", "options": [{"text": "Deliver data-literacy training to maternity and ED teams so more clinicians can interrogate the dashboards themselves.", "feedback": "Training may support future capability, but the scenario identifies insufficient opportunity and role clarity—not lack of basic analytical knowledge.", "branch": "Staff gain skills but still have no time or accountable process for evidence review."}, {"text": "Establish protected clinical–analytical–operational review time, named interpretation and action responsibilities, and feedback to the learning community.", "feedback": "Best-supported: like clinical AI implementation, data-to-action depends on the people, workflow and authority surrounding the technology.", "branch": "Existing technical capability becomes connected to clinical interpretation and operational decisions."}, {"text": "Recruit a specialist implementation scientist to develop a workflow and lead evaluation for the first six months.", "feedback": "Implementation expertise could contribute, but one temporary appointment does not solve ongoing protected participation across disciplines.", "branch": "Expertise expands while the multidisciplinary operating arrangement remains unresolved."}, {"text": "Introduce automated alerts for repeat maternity presentations so clinical teams can respond sooner without waiting for monthly reports.", "feedback": "Automation might be investigated later, but clinical need, alert validity, response pathways and safety have not been established.", "branch": "A new technology creates untested workload and accountability demands."}], "correct": 1, "newEvidence": "Comparative research clue: TREWS and other AI sepsis implementations underline human–machine teaming, trust, role clarity and workflow opportunity. This is a transfer example, not evidence about the pregnancy outcome."}, {"title": "Translation–2 · Sustain capability", "prompt": "A pilot team produces useful findings, but the analyst is seconded for only three months. What should be done?", "options": [{"text": "Complete the first analysis before the secondment ends and archive the code.", "feedback": "Preserves artefacts but not necessarily repeatable learning.", "branch": "Ongoing interpretation and feedback may stop."}, {"text": "Agree a sustainable operating model for analysis, clinical interpretation, governance, feedback and maintenance.", "feedback": "Best: creates repeatable organisational capability.", "branch": "Assign ongoing resource and accountability."}, {"text": "Commission an external evaluator at the end of the pilot.", "feedback": "Independent evaluation can help but does not maintain everyday feedback.", "branch": "Internal ownership remains important."}, {"text": "Train a clinician to run the existing analytic scripts.", "feedback": "May reduce dependence on the analyst but not cover data access, interpretation or process ownership.", "branch": "Consider the whole translation chain."}], "correct": 1, "newEvidence": "Additional evidence: existing data reports are produced, but no role is formally responsible for turning findings into jointly agreed service changes."}], "clue": "A translation capability connects data, clinical judgement, patients, operations and implementation over time.", "basis": "Bian et al. 2026; McDonald et al. 2022."}], "synthesis": [{"title": "Synthesis–1 · Prioritise workforce readiness", "prompt": "What should the initial readiness investment fund?", "options": [{"text": "Mandatory training for all ED and maternity staff.", "feedback": "Training may follow, but current constraints centre on roles, capacity and collaboration.", "branch": "Avoid treating every barrier as knowledge deficit."}, {"text": "A dedicated coordinator role without changing existing workflows.", "feedback": "Could help but may simply add a parallel process and cost.", "branch": "Define the operating model first."}, {"text": "A small resourced cross-service team that clarifies roles, validates evidence and tests feasible coordination arrangements.", "feedback": "Best: targeted capability with manageable initial scope.", "branch": "Set accountability, time and continuation criteria."}, {"text": "A large-scale maturity assessment across all hospital professions.", "feedback": "Broad assessment may be costly and disconnected from the scoped learning question.", "branch": "Prioritise context-specific diagnostic work."}], "correct": 2, "newEvidence": "The service has motivated clinicians and analysts, but no confirmed coordinated roles, protected time or cross-sector working arrangements."}, {"title": "Synthesis–2 · Judge readiness", "prompt": "Which conclusion is most justified?", "options": [{"text": "Staff are ready, and the remaining challenge is communication.", "feedback": "Positive attitude alone does not establish opportunity.", "branch": "Capacity remains an evidenced unknown."}, {"text": "Motivation appears positive, but feasibility, role clarity and after-hours opportunity require assessment before pathway implementation.", "feedback": "Best: distinguishes motivation and capability from conditions to act.", "branch": "Test real workflows and safety requirements."}, {"text": "The initiative should be cancelled until additional staff can be hired.", "feedback": "Resource constraints warrant investigation but cancellation is premature.", "branch": "Consider phased or redesigned scope."}, {"text": "A digital handover tool should replace the need for specialist availability.", "feedback": "Technology cannot substitute for clinical decision authority or capacity.", "branch": "Assess safe staffing and escalation."}], "correct": 1, "newEvidence": "An employee survey reports strong support for coordination; operational leaders have not identified reliable after-hours capacity."}], "number": 6, "literature": [{"label": "McDonald et al., LHS competencies (2022)", "url": "https://doi.org/10.1136/bmjopen-2022-061124"}, {"label": "Henry et al., TREWS workforce adoption (2022)", "url": "https://doi.org/10.1038/s41591-022-01895-z"}], "workshopBridge": "Identify competencies, opportunity and resourced roles for clinical, analytical and operational learning."}, {"title": "The Governance Office", "topic": "Enabling governance, ethics and equity", "subtitle": "The most efficient route is not always the most accountable. Which decisions and safeguards must be established?", "lobby": "A usual gestational-age access arrangement generally directed patients under 20 weeks to ED. A specialist later arranged direct birth-suite access for this patient at approximately 18 weeks. The learning team wants to assess access arrangements and use routine care data to investigate comparable journeys.", "mission": "Clarify accountability, cross-organisational governance, proportionate ethical oversight and equitable access without prescribing a clinical policy change.", "conclusion": "Enabling governance defines authority and safeguards for reliable learning and responsible adaptation. It can streamline appropriate oversight without eliminating it, and it must address who benefits or is excluded.", "fields": [["population", "Who is included and affected?", "Eligibility and equity considerations."], ["learning", "Governance question for the scope", "Which proposed investigation or change needs approval?"], ["sources", "Relevant clinical, legal and patient evidence", "What must decision-makers review?"], ["quality", "Safety, privacy and equity risks", "Risks and unresolved assumptions."], ["governance", "Accountable decision and approval routes", "Clinical, information, ethics and external agreements."], ["investment", "First governance capability to establish", "Proportionate oversight and decision path."]], "refs": ["Foley & Horwitz (2025), Strategy, structure and governance.", "Steel et al. (2025), ACQUIRE example and IRB/QI review.", "Curcin et al. (2026), Trustworthy LHS/AI governance.", "Australian NSQHS Communicating for Safety Standard.", "NHMRC guidance on quality assurance and evaluation."], "witnesses": [{"id": "clinical", "name": "The clinical governance director", "role": "Safety and access policies", "short": "Who can authorise a change to access pathways?", "intro": "The patient encountered the usual gestational-age service boundary, and a specialist subsequently arranged an individualised access plan. The team wants to understand the policy and potential alternatives.", "opening": "Simulated clinical governance briefing: “The gestational policy may reflect clinical staffing, resources and escalation capability. We should examine its purpose and impact before changing it.”", "q": [{"title": "Clinical–1 · Review the policy", "prompt": "What is the most defensible action before standardising a new access pathway?", "options": [{"text": "Permit specialist-authorised exceptions while collecting data on how often they occur.", "feedback": "This may support current care but does not establish system-wide safety or equity.", "branch": "Exceptions alone can create uneven access."}, {"text": "Review clinical eligibility, policy rationale, escalation arrangements, capacity and patient outcomes with relevant stakeholders.", "feedback": "Best: provides a governed basis for deciding whether and how to adapt.", "branch": "Include operational and patient evidence."}, {"text": "Retain the present threshold until a comparative trial demonstrates a better option.", "feedback": "The evidence base matters, but formal trial evidence is not always necessary to review policy.", "branch": "Proportionate evaluation may be appropriate."}, {"text": "Adopt the specialist’s individualised solution for all comparable patients.", "feedback": "A single case cannot establish universal eligibility or safety.", "branch": "Assess feasibility and unintended effects."}], "correct": 1, "newEvidence": ""}, {"title": "Clinical–2 · Define authority", "prompt": "ED and maternity leaders agree that pathway review is needed but differ over who may authorise changes. What first step is strongest?", "options": [{"text": "Ask the maternity director to issue a clinical instruction and monitor use.", "feedback": "Clinical leadership matters but ED and operational accountabilities also need agreement.", "branch": "Do not unilaterally redefine shared responsibilities."}, {"text": "Create a separate LHS governance body with authority over all clinical protocols.", "feedback": "May duplicate or conflict with established governance.", "branch": "Integrate with existing clinical safety structures."}, {"text": "Map existing clinical and operational decision rights, nominate an accountable owner and establish a joint approval and escalation route.", "feedback": "Best: clarity before action, with appropriate oversight.", "branch": "Document decisions, exceptions and review criteria."}, {"text": "Leave decisions with the treating specialist for each patient.", "feedback": "Individual decisions remain necessary, but routine policy may need organisational governance.", "branch": "Reduce arbitrary variation through clear processes."}], "correct": 2, "newEvidence": "Additional evidence: the birth suite’s resources and eligibility criteria may differ from ED; safe access policies need clinical and operational design."}], "clue": "Clinical pathway change needs proportionate review, clear approval authority and attention to system capacity.", "basis": "Foley & Horwitz 2025; NSQHS communicating for safety."}, {"id": "privacy", "name": "The information governance officer", "role": "Secondary data use and ethical review", "short": "Can the LHS use care data quickly and responsibly?", "intro": "The team proposes linking hospital administrative and maternity information with selected GP and patient-experience data for a quality improvement investigation.", "opening": "Simulated governance note: “Each data source has a custodian, a purpose and access requirements. Ethics review obligations must be determined based on the activity, not its label.”", "q": [{"title": "Governance–1 · Establish a data route", "prompt": "What is the best initial governance action for linked cross-service analysis?", "options": [{"text": "Use a de-identified export because it avoids all privacy and approval issues.", "feedback": "De-identification may reduce risk but does not automatically eliminate lawful access or governance duties.", "branch": "Linkage and re-identification risks still need assessment."}, {"text": "Ask the hospital HREC to approve the entire initiative before specifying data requirements.", "feedback": "HREC review may be needed, but scope, purposes and data flows must first be described.", "branch": "The appropriate pathway depends on activity and rules."}, {"text": "Document purposes, custodians, data flows, safeguards and relevant approvals, then obtain proportionate determinations and agreements.", "feedback": "Best: aligns oversight with actual proposed activity.", "branch": "Specify authority for access, linkage and reporting."}, {"text": "Use data only from public hospital systems to avoid cross-sector complications.", "feedback": "May be a feasible phase, but could make the research question unanswerable.", "branch": "Record exclusions and residual bias."}], "correct": 2, "newEvidence": ""}, {"title": "Governance–2 · Interpret an ethics shortcut", "prompt": "A manager says that because the project is “quality improvement”, ethics review can be bypassed. What is the best reply?", "options": [{"text": "Quality improvement projects never need HREC review if only routine care data are used.", "feedback": "This is not a safe blanket rule in Australia.", "branch": "Oversight depends on risk, purpose and institutional requirements."}, {"text": "Any project analysing patient information must undergo full HREC review.", "feedback": "Overly categorical; proportionate review or other authorisation may be appropriate.", "branch": "Seek a documented local determination."}, {"text": "Governance should expedite proportionate review, with documented decisions and privacy, consent and patient safeguards as applicable.", "feedback": "Best: supports timely learning without bypassing protection.", "branch": "Use institutional pathways and relevant NHMRC guidance."}, {"text": "The project can start on aggregate results and request approval later if individual records are needed.", "feedback": "Some aggregate uses may be permitted, but retrospective approval is not a substitute for determining requirements.", "branch": "Clarify governance before use."}], "correct": 2, "newEvidence": "Additional evidence: UC San Diego’s ACQUIRE approach includes IRB representatives to coordinate and expedite ethical QI and research, not to waive requirements indiscriminately."}], "clue": "Fast learning requires proportionate governance, documented authority and safeguards—not an ethics bypass.", "basis": "Steel et al. 2025; NHMRC guidance."}, {"id": "equity", "name": "The patient equity adviser", "role": "Equity and patient access", "short": "Who would benefit from a new access route?", "intro": "The individualised pathway was arranged following specialist review. The team must consider patients who do not have an established specialist relationship or easy transport.", "opening": "Simulated equity briefing: “Two people with comparable clinical needs may differ in language, distance, finances, access to specialist care and ability to contact hospital services.”", "q": [{"title": "Equity–1 · Define fair access", "prompt": "What is the strongest question when evaluating a proposed coordinated pathway?", "options": [{"text": "Does the pathway offer the same instructions to all eligible patients?", "feedback": "Uniform instructions do not guarantee equitable understanding or access.", "branch": "Examine actual barriers and support."}, {"text": "Does the pathway reduce presentations among those already accessing private specialist care?", "feedback": "This subgroup may be easier to reach but is not representative of all patients.", "branch": "Assess those without established specialist connections."}, {"text": "Are access and outcomes appropriate across groups with comparable clinical needs, including those facing social and geographic barriers?", "feedback": "Best: tests equity in reach, usability and outcomes.", "branch": "Plan stratified monitoring and qualitative feedback."}, {"text": "Can the pathway be delivered without additional hospital funding?", "feedback": "Feasibility matters, but no-cost arrangements can redistribute burdens unfairly.", "branch": "Include resources and equity in appraisal."}], "correct": 2, "newEvidence": ""}, {"title": "Equity–2 · Adjust implementation", "prompt": "A patient survey shows improved access, but responses come mainly from patients with private obstetricians. What is the best next step?", "options": [{"text": "Report the positive result but flag the sample limitation and seek other patient experiences before deciding broader benefit.", "feedback": "Best: credible reporting and targeted equity evidence.", "branch": "Recruit underserved groups and examine differential reach."}, {"text": "Weight responses statistically to estimate the experience of patients without private care.", "feedback": "Weighting can help with known sampling structures but cannot replace missing experiential evidence automatically.", "branch": "Assess representativeness and assumptions."}, {"text": "Limit the pathway to patients with established specialist care because this group appears to benefit.", "feedback": "May entrench disparities and cannot establish overall clinical or operational appropriateness.", "branch": "Review eligibility and support needs."}, {"text": "Launch a second survey at a later time but continue implementation unchanged.", "feedback": "Additional data may help but known gaps warrant proportionate investigation and adaptation.", "branch": "Assess access barriers now."}], "correct": 0, "newEvidence": "Additional evidence: the available evaluation sample under-represents patients without private care and those facing transport or language barriers."}], "clue": "Patient protection includes equity and representativeness, not only privacy and protocol compliance.", "basis": "Menear et al. 2019; Ye et al. 2026."}], "synthesis": [{"title": "Synthesis–1 · Choose the oversight model", "prompt": "Which governance design is most defensible?", "options": [{"text": "Create a new programme committee with exclusive authority over all aspects of the initiative.", "feedback": "May duplicate established clinical and ethics governance and exceed the committee’s legitimate authority.", "branch": "Map existing routes first."}, {"text": "Use separate clinical, information and ethics approvals with no shared oversight to preserve independence.", "feedback": "Expert oversight remains important but uncoordinated approvals can obscure whole-system responsibility.", "branch": "Provide a coordinated decision map."}, {"text": "Appoint a sponsor and establish a linked clinical, operational, information and ethical decision route, including partner agreements and equity review.", "feedback": "Best: proportionate, integrated and accountable.", "branch": "Define scope and escalation before implementation."}, {"text": "Delegate governance to maternity because the principal clinical population is pregnant patients.", "feedback": "Maternity leadership is necessary but not sufficient for multi-service data and decisions.", "branch": "Include external custodians and appropriate committees."}], "correct": 2, "newEvidence": "The investigation spans clinical pathway policy, routine data, partner organisations and patient access."}, {"title": "Synthesis–2 · Scope the initial work", "prompt": "What can proceed responsibly?", "options": [{"text": "Implement direct access for selected patients while approvals and safety review are completed in parallel.", "feedback": "May be justified for individual clinical care but not as a blanket LHS intervention without governance.", "branch": "Separate current clinical decision from a new service-wide policy."}, {"text": "Complete a bounded feasibility and policy review, obtain applicable authorisations and involve relevant patients and services before intervention design.", "feedback": "Best: feasible initial LHS discovery with safeguards.", "branch": "Document no-go conditions and the next governance decision."}, {"text": "Postpone all learning activities until a large research programme is approved.", "feedback": "Overly restrictive; proportionate preliminary scoping may be possible.", "branch": "Match review to risk and activity."}, {"text": "Use only existing anonymous administrative reports and avoid patient contact.", "feedback": "May limit governance requirements but likely misses the central learning question and equity.", "branch": "Do not remove necessary evidence solely to simplify approvals."}], "correct": 1, "newEvidence": "The policy review is incomplete, data agreements are unresolved and no wider intervention benefit has been demonstrated."}], "number": 7, "literature": [{"label": "Steel et al., LHS strategy and ethics governance (2025)", "url": "https://doi.org/10.1038/s44401-025-00029-0"}, {"label": "Curcin et al., Trustworthy AI in an LHS (2026)", "url": "https://doi.org/10.1016/j.artmed.2025.103346"}], "workshopBridge": "Define proportional data/ethics approvals, patient safety, authority and equitable access."}, {"title": "The LHS Boardroom", "topic": "Change management and sustained improvement", "subtitle": "The case is closed clinically. The organisational learning challenge remains: what capability should be built first and how will it last?", "lobby": "The patient’s condition eventually deteriorated with haemorrhage and infection, and the pregnancy ended in a second-trimester loss. This outcome cannot be presumed preventable. The learning community proposes improving cross-service continuity for comparable patients and asks what is feasible, safe, equitable and sustainable.", "mission": "Prioritise barriers before strategies, distinguish implementation from patient benefit and establish a sustainable LHS discovery charter.", "conclusion": "The first credible investment is a bounded, governed and resourced learning capability with a shared question, interdisciplinary team, feasible evidence plan and feedback/evaluation mechanism. It is not proof that a given intervention will improve outcomes.", "fields": [["population", "Initial scope and boundaries", "Population, services and inclusion/exclusion rationale."], ["learning", "Learning aim and next testable question", "What will be established before changing care?"], ["sources", "Evidence and community needed", "Which data, people and expertise?"], ["quality", "Determinants, unintended consequences and equity", "What barriers or risks require attention?"], ["governance", "Sponsor, oversight and sustainability", "Who is accountable and how is it resourced?"], ["investment", "First capability investment and evaluation", "What happens first, what would justify continuation?"]], "refs": ["Foley & Horwitz (2025), Implementation, behaviour change and evaluation.", "Damschroder et al. (2022), Updated CFIR.", "Powell et al. (2015), ERIC implementation strategies.", "Proctor et al. (2011), Implementation outcomes.", "Somerville et al. (2023), LHS implementation strategies review.", "Bian et al. (2026), Learning utility (perspective).", "Bian et al. (2026) Three-layer learning utility model; https://doi.org/10.1038/s44401-026-00107-x", "Lane et al. (2026) Evidence surveillance, implementation and sustainability; https://doi.org/10.1186/s13012-025-01482-z"], "witnesses": [{"id": "implementation", "name": "The implementation scientist", "role": "Barrier diagnosis and strategy matching", "short": "What needs to change before choosing an intervention?", "intro": "The learning team proposes a coordinated maternity approach. Stakeholders support its purpose but differ about workflows, data access and operational responsibilities.", "opening": "Simulated determinant summary: the innovation is not fully specified, clinical capacity is uncertain, cross-sector information sharing is variable, and the implementation team lacks protected time.", "q": [{"title": "Implementation–1 · Diagnose before prescribing", "prompt": "Which next step best applies implementation science?", "options": [{"text": "Pilot the new clinical pathway in one ward and collect adoption data.", "feedback": "A pilot may be useful later, but feasibility and clinical scope remain unresolved.", "branch": "Do not treat an unready intervention as ready."}, {"text": "Identify and prioritise implementation determinants across innovation, settings, individuals and process before selecting strategies.", "feedback": "Best: directly applies the logic of CFIR and contextual diagnosis.", "branch": "Match each strategy to a specific evidenced barrier."}, {"text": "Deliver standard implementation training to all teams to develop shared understanding.", "feedback": "Education may help knowledge gaps but not capacity, governance or workflow barriers.", "branch": "Determine the mechanism before selecting the response."}, {"text": "Appoint a pathway champion and use feedback to build staff support.", "feedback": "A champion helps engagement but cannot independently address all barriers.", "branch": "Address organisational feasibility and data needs."}], "correct": 1, "newEvidence": ""}, {"title": "Implementation–2 · Match strategy to problem", "prompt": "Staff understand the pathway but cannot identify who must coordinate after-hours cases. Which implementation strategy best fits?", "options": [{"text": "Conduct more education on the importance of continuity.", "feedback": "The problem is unclear authority and coverage, not necessarily knowledge.", "branch": "Training alone may leave the barrier unchanged."}, {"text": "Audit and publish each clinician’s pathway compliance.", "feedback": "Compliance metrics may misrepresent an undefined or infeasible process.", "branch": "Clarify responsibilities before auditing."}, {"text": "Co-design and test role clarity, escalation and coverage arrangements with operational and clinical teams.", "feedback": "Best: addresses the observed determinant directly.", "branch": "Assess fidelity, feasibility and unintended effects."}, {"text": "Change the electronic record to automatically alert the birth suite.", "feedback": "Alerts may help communication but not who decides or responds.", "branch": "Build clinical capacity and accountability."}], "correct": 2, "newEvidence": "Additional evidence: a previous education campaign improved awareness but did not change the after-hours handover constraints."}], "clue": "Strategy choice follows diagnosis of the implementation barrier, not a generic intervention menu.", "basis": "CFIR 2022; ERIC 2015."}, {"id": "operations", "name": "The maternity operations director", "role": "Feasibility, workload and sustainment", "short": "Can a benefit to one service create a cost elsewhere?", "intro": "A simulated pilot shows fewer ED presentations among a selected group, but maternity staff report extra coordination work and inconsistent use across shifts.", "opening": "Simulated service report: the number of ED presentations fell in the target cohort, while specialist consultation time increased and no clinical safety comparison has yet been completed.", "q": [{"title": "Operations–1 · Interpret a promising result", "prompt": "Which conclusion is strongest?", "options": [{"text": "The pathway has reduced avoidable ED presentations and is ready to expand.", "feedback": "Avoidable has not been clinically established and balancing harms are unknown.", "branch": "Examine appropriateness and workload."}, {"text": "The pathway is failing because maternity workload has increased.", "feedback": "Added workload may be justified by benefit, but the net effect is not known.", "branch": "Investigate workload and outcomes."}, {"text": "There is promising operational change, but patient benefit, clinical safety, equity and workload need evaluation.", "feedback": "Best: weighs positive and balancing results without overclaiming.", "branch": "Use linked service and patient measures."}, {"text": "The main next step is to improve compliance across shifts.", "feedback": "Variation may be caused by feasibility, not just adherence.", "branch": "Investigate determinants of inconsistent use."}], "correct": 2, "newEvidence": ""}, {"title": "Operations–2 · Build sustainability", "prompt": "The original champion and analyst will leave when the pilot funding ends. What capability most needs to be established?", "options": [{"text": "A permanent dashboard to preserve the results and monitor future use.", "feedback": "Dashboards support observation but do not assign action or resources.", "branch": "An owner and review process remain necessary."}, {"text": "Routine ownership, resourcing, feedback review and processes for adapting and maintaining the pathway.", "feedback": "Best: creates a repeatable operating capability beyond champions.", "branch": "Specify cadence, budget and escalation."}, {"text": "A final external evaluation report for executive endorsement.", "feedback": "May support a funding decision but not maintain day-to-day learning.", "branch": "Keep operational responsibility active."}, {"text": "Additional training before the pilot concludes.", "feedback": "Useful for capability but cannot replace leadership and ongoing resources.", "branch": "Design organisational continuity."}], "correct": 1, "newEvidence": "Additional evidence: the pilot depended heavily on one champion and temporary analytical support, creating a risk of capability loss."}], "clue": "Sustainment is the repeated ability to monitor, decide and adapt—not simply completion of an implementation.", "basis": "Proctor et al. 2011; Foley & Horwitz 2025."}, {"id": "patient", "name": "The patient and GP panel", "role": "Patient benefit, equity and continuity", "short": "Whose improvement counts after launch?", "intro": "A simulated patient survey reports better understanding of whom to contact, but uptake is lower among patients without private specialist relationships and distant patients.", "opening": "Simulated joint patient and GP panel: “The new route may help some people; we need to know if clinically comparable patients can access it and whether GP follow-up is clearer.”", "q": [{"title": "Patient–1 · Select a meaningful outcome set", "prompt": "Which evaluation package most appropriately measures system-wide value?", "options": [{"text": "Reduced ED visits plus patient satisfaction and staff training completion.", "feedback": "Useful measures but omit clinical appropriateness, equity and workload.", "branch": "Define balancing and safety outcomes."}, {"text": "Improved clinical outcomes and maternity bed utilisation alone.", "feedback": "These matter but may not reveal continuity, reach or lived experience.", "branch": "Combine implementation and service outcomes."}, {"text": "Safe and clinically appropriate access, care continuity, patient experience, equitable reach, adoption and workload.", "feedback": "Best: balances patient, service and implementation outcomes.", "branch": "Specify suitable operational definitions."}, {"text": "Patient-reported continuity and GP receipt of discharge correspondence.", "feedback": "Important but not sufficient for safety, operational feasibility and equitable access.", "branch": "Broaden outcome domains."}], "correct": 2, "newEvidence": ""}, {"title": "Patient–2 · Respond to unequal uptake", "prompt": "The pilot benefits appear concentrated among patients with established specialist relationships. What is the best response?", "options": [{"text": "Scale the programme for the benefiting group first and assess equity during later expansion.", "feedback": "Phased scope may sometimes be sensible but can entrench a known access gap.", "branch": "Consider equity before expansion."}, {"text": "Analyse reach by relevant patient groups, investigate barriers with those underrepresented and adapt access arrangements before broad scale-up.", "feedback": "Best: uses equity evidence to guide implementation adaptation.", "branch": "Document changes and re-evaluate reach."}, {"text": "Provide the same information sheet to all eligible patients.", "feedback": "Consistent information does not assure practical access or understanding.", "branch": "Check structural barriers."}, {"text": "Use statistical adjustment to estimate benefit among groups with low uptake.", "feedback": "Analysis may help but cannot substitute for participation and real-world access evidence.", "branch": "Seek additional data and lived experience."}], "correct": 1, "newEvidence": "Additional evidence: the evaluation sample under-represents rural patients and those without private specialist care, limiting claims of equitable benefit."}], "clue": "LHS value should include appropriate care, continuity, equitable reach and consequences, not a single operational metric.", "basis": "Menear et al. 2019; Proctor et al. 2011."}], "synthesis": [{"title": "Synthesis–1 · Scope the first LHS investment", "prompt": "Which starting investment is most defensible under a modest discovery budget?", "options": [{"text": "Establish a bounded, resourced and governed learning community with a shared question, data-feasibility work and a feedback/evaluation plan.", "feedback": "Best: builds minimum viable learning capability before intervention selection.", "branch": "Specify a stop/go decision and continuation criteria."}, {"text": "Implement direct maternity access for eligible patients and learn from the results.", "feedback": "A clinical intervention may follow, but eligibility and governance are not yet established.", "branch": "Avoid launching before critical prerequisites."}, {"text": "Purchase interoperability software to connect GP and hospital records.", "feedback": "Information linkage may eventually help, but the learning question, partners and governance are not fully specified.", "branch": "Technology alone does not build an LHS."}, {"text": "Create an organisation-wide LHS office to oversee all future improvement programmes.", "feedback": "Could be appropriate at scale but may exceed the initial scope and resources.", "branch": "Start with a credible bounded capability."}], "correct": 0, "newEvidence": "The organisation has a shared concern, partial data capability, motivated stakeholders and gaps in cross-service authority, roles and evidence."}, {"title": "Synthesis–2 · From project to learning utility", "prompt": "The six-month pilot creates reports and an initial pathway, but its analyst and clinical champion will leave. Which evidence would most convincingly show that an LHS capability has been established?", "options": [{"text": "The pathway has been incorporated into the clinical policy manual, and staff have completed training.", "feedback": "Policy and training are valuable adoption supports, but they do not demonstrate continuing evidence surveillance, monitoring or adjustment.", "branch": "The organisation may preserve the intervention without preserving the ability to learn."}, {"text": "Hospital dashboards automatically refresh, and a leadership group receives quarterly performance reports.", "feedback": "Reliable reporting is one technical foundation, but it does not establish stakeholder interpretation, accountability or improvement feedback.", "branch": "The data machinery continues without documented decisions or patient contribution."}, {"text": "The cross-service learning community has allocated ownership, governed and clinically validated evidence, a regular external-evidence and outcome review, documented decisions and the ability to adapt care.", "feedback": "Best-supported: this connects data foundations, feedback machinery and enabling organisational arrangements into a reusable learning capability.", "branch": "The organisation retains a functioning capacity to learn after the initial project and personnel change."}, {"text": "The pilot demonstrates a reduction in recurrent ED attendance sustained over six months with no major increase in maternity workload.", "feedback": "This would be promising, if clinically appropriate and equitable, but represents outcomes of one project rather than proof of reusable learning infrastructure.", "branch": "The initiative is judged on a metric without demonstrating sustained capability to investigate future questions."}], "correct": 2, "newEvidence": "Final board reveal: technical foundations, monitoring/feedback machinery and an enabling environment are all required. Evidence surveillance, workforce opportunity, patient involvement, clinical governance and sustained ownership connect them."}], "number": 8, "literature": [{"label": "Damschroder et al., updated CFIR (2022)", "url": "https://doi.org/10.1186/s13012-022-01245-0"}, {"label": "Powell et al., ERIC strategies (2015)", "url": "https://doi.org/10.1186/s13012-015-0209-1"}, {"label": "Proctor et al., Implementation outcomes (2011)", "url": "https://doi.org/10.1007/s10488-010-0319-7"}, {"label": "Bian et al., Learning utility (2026)", "url": "https://doi.org/10.1038/s44401-026-00107-x"}], "workshopBridge": "Prioritise readiness investments and define implementation, balancing measures and a sustainable learning utility."}];
window.LHS_CARDS = [{"title": "1 · Executive strategy", "speaker": "Chief Executive and Strategy Director", "text": "The strategic plan prioritises patient-centred care, integration and digital transformation. The executive supports a complex maternity care investigation and operates an established QI committee. However, no dedicated LHS budget exists and no sponsor owns cross-service coordination.", "focus": "Shared purpose, leadership commitment, resources, accountability"}, {"title": "2 · Primary care partnership", "speaker": "GP and primary-care network representative", "text": "Local GP practices maintain their own records and use established referral and correspondence routes. A GP representative is willing to participate, but practices are independent organisations; resource commitments and any use of identifiable data would need agreements.", "focus": "System boundary, inter-organisational participation, data custody"}, {"title": "3 · Patient partnership", "speaker": "Consumer Partnership Manager", "text": "The hospital has an established patient advisory council and collects experience feedback. However, few representatives have experience of complex maternity pathways. Patients have not yet co-defined the learning question or the outcome measures.", "focus": "Co-production, representation, patient-reported evidence, equity"}, {"title": "4 · Clinical learning culture", "speaker": "Clinical Quality and Safety Director", "text": "The service runs case reviews, morbidity and mortality meetings, and incident investigations. These support local learning, but cross-service reviews are uncommon and feedback on changes is inconsistent. Formal clinical accountability channels remain available.", "focus": "Psychological safety, fair review, adaptation, feedback"}, {"title": "5 · Data and evidence", "speaker": "CIO, Data Lead and Clinical Librarian", "text": "The hospital has an electronic record, data warehouse, and analysts who report activity and waiting times. Cross-service cohort definitions have not been validated; GP/private specialist information is not routinely available for secondary analysis. The library provides access to research, but ongoing evidence surveillance and synthesis are ad hoc rather than governed as a standing service.", "focus": "Data quality, interoperability, literature surveillance, learning utility"}, {"title": "6 · Workforce and operations", "speaker": "Maternity Manager and Analytics Lead", "text": "Experienced clinicians, analysts, informaticians and improvement-trained staff are available. They do not routinely work together across ED, maternity and primary care; protected time, clinical validation responsibilities and evidence-to-action ownership have not been agreed.", "focus": "Skills versus opportunity, interprofessional translation, roles"}, {"title": "7 · Governance and equity", "speaker": "Clinical Governance, Information Governance and Consumer Advisers", "text": "The organisation has established quality/safety, privacy and research governance. The cross-service data-access route and approval responsibilities for the proposed work are not yet agreed. A future access pathway would also require clinical capacity assessment and evaluation of reach among patients without established specialist care.", "focus": "Safety, proportionate oversight, data governance, fairness"}, {"title": "8 · Improvement infrastructure", "speaker": "Quality Improvement and Evaluation Team", "text": "The service has delivered local audit, PDSA and evaluation projects. Many depend on short-term champions or funding; there is not yet an established process combining external evidence review, patient feedback, approved analytics, accountable decisions and monitoring across the proposed learning network.", "focus": "Implementation, feedback machinery, sustainability, three-layer learning utility"}];
window.LHS_CHECKPOINTS = [{"title": "Checkpoint A · What system are we scoping?", "rooms": [1, 2], "prompt": "Use the GP and executive evidence to define a meaningful bounded population and cross-service interface. State the shared learning aim, sponsor, and one serious unknown.", "fields": ["Boundary and included services", "Shared learning aim", "Sponsor / commitment versus efficacy", "Important assumption or missing evidence"]}, {"title": "Checkpoint B · Who enables learning?", "rooms": [3, 4], "prompt": "Show how the learning community will involve patients, primary care and hospital staff. Define how disagreements and clinical uncertainty will be handled.", "fields": ["Essential partners and their influence", "How the problem definition changed", "Psychologically safe review and accountability", "Feedback mechanism and unresolved concern"]}, {"title": "Checkpoint C · Can evidence become action?", "rooms": [5, 6], "prompt": "Assess whether technical data and external evidence can inform a clinically meaningful question, and whether people have time and responsibility to use them.", "fields": ["Minimum usable data and research evidence", "Quality/access/applicability uncertainties", "Existing expertise and opportunity gaps", "First realistic capability investment"]}, {"title": "Checkpoint D · Will improvement be trustworthy and sustained?", "rooms": [7, 8], "prompt": "Define decision authority and safeguards. Identify the first bounded learning investment and what would demonstrate a reusable capability rather than a one-off project.", "fields": ["Clinical / information / ethical / equity governance", "Key CFIR determinant and plausible ERIC response", "Implementation, patient, equity and balancing outcomes", "Sustained owner, feedback loop and next decision gate"]}];
window.LHS_READINESS = [["Systems thinking and scope", "Meaningful cross-service boundary and testable learning question"], ["Shared purpose and leadership", "Strategic commitment, accountable sponsor, roles and resources"], ["Learning community", "Appropriate representation, shared interpretation and actual influence"], ["Learning culture", "Psychological safety, fair accountability, feedback and adaptation"], ["Data and evidence capability", "Quality, access, interoperability, synthesis and actionable feedback"], ["Workforce readiness", "Clinical, analytical and implementation expertise, time, opportunity and support"], ["Enabling governance", "Clinical safety, data/ethics, decision authority, privacy and equity"], ["Change and sustained improvement", "Implementation capacity, outcomes, balancing measures and ongoing ownership"]];
